// Üretilen dosya: tool/ozgun/uret.py. Teknoloji · Bilgisayar donanımı ve işletim sistemleri (orta).
const ozTechnology1Orta = <(String, String, List<String>, String)>[
  ('Sıradaki yürütülecek komutun bellek adresini tutan işlemci yazmacının adı nedir?', 'Program sayacı (PC)', ['Akümülatör yazmacı', 'Bayrak yazmacı', 'Yığın işaretçisi (SP)'], 'Program sayacı bir sonraki komutun adresini saklar; her komut getirildiğinde genellikle bir sonraki komuta işaret edecek biçimde güncellenir.'),
  ('Bir işlemcide yazmaçların (register) ana bellekten çok daha hızlı erişilmesinin temel nedeni nedir?', 'İşlemci yongasının içinde bulunmaları', ['Manyetik ortamda veri tutmaları', 'Kapasitelerinin onlarca gigabayta ulaşması', 'Verileri sıkıştırarak saklamaları'], 'Yazmaçlar işlemcinin içinde, ALU\'ya en yakın yerde bulunan çok küçük ve çok hızlı depolama hücreleridir; bu yüzden tek saat çevriminde erişilebilirler.'),
  ('Bir toplama işleminin sonucu sıfır çıktığında işlemcide bu durumu kaydeden yapı hangisidir?', 'Durum (bayrak) yazmacındaki sıfır biti', ['Komut yazmacı', 'Bellek adres yazmacındaki en yüksek bit', 'Önbellek etiketi'], 'Durum yazmacı, son işlemin sonucuna göre sıfır, elde, taşma ve işaret gibi bayrakları tutar; koşullu dallanma komutları bu bayraklara bakar.'),
  ('İşlemcinin, bellekten okunacak ya da belleğe yazılacak verinin adresini geçici olarak tuttuğu yazmaç hangisidir?', 'MAR (bellek adres yazmacı)', ['MDR (bellek veri yazmacı)', 'IR (komut yazmacı)', 'SP (yığın işaretçisi yazmacı)'], 'MAR erişilecek bellek konumunun adresini tutar; o adresteki veri ise MDR üzerinden taşınır.'),
  ('Saat hızı 4 GHz olan bir işlemcide tek bir saat çevrimi kaç nanosaniye sürer?', '0,25 ns', ['4 ns', '0,025 ns', '0,4 ns'], 'Periyot frekansın tersidir: 1 / (4×10⁹ Hz) = 0,25×10⁻⁹ s, yani 0,25 nanosaniye.'),
  ('Intel\'in Hyper-Threading adını verdiği eşzamanlı çoklu iş parçacığı (SMT) tekniği ne sağlar?', 'Bir fiziksel çekirdeğin iki mantıksal çekirdek gibi görünmesini', ['İşlemcinin saat hızının iki katına çıkmasını', 'İki ayrı fiziksel işlemcinin tek bir soket üzerinde birleştirilmesini', 'Önbellek boyutunun iki katına çıkmasını'], 'SMT, bir çekirdeğin boşta kalan yürütme kaynaklarını ikinci bir iş parçacığına açar; fiziksel çekirdek sayısı değişmez ama mantıksal çekirdek sayısı artar.'),
  ('İşlemci üreticilerinin belirttiği TDP değeri neyi ifade eder?', 'Soğutucunun atması gereken tipik ısı miktarını', ['İşlemcinin turbo kipteki en yüksek saat hızını', 'Desteklenen en büyük RAM miktarını', 'İşlemcinin transistör sayısını'], 'TDP (Thermal Design Power), soğutucunun tipik yük altında atması gereken ısıyı watt cinsinden belirten bir tasarım değeridir.'),
  ('L1, L2 ve L3 önbellek düzeyleri için hangi genelleme doğrudur?', 'L1 en küçük ve en hızlı, L3 en büyük ve en yavaş olanıdır', ['L3 en küçük ve en hızlı olanıdır', 'Üçünün boyutu ve hızı aynıdır', 'L2 her zaman ana bellekten (RAM) daha yavaş çalışan düzeydir'], 'Çekirdeğe yaklaştıkça önbellek küçülür ve hızlanır; L3 genellikle çekirdekler arasında paylaşılan, daha büyük ama görece yavaş düzeydir.'),
  ('İşlemci önbelleklerinde en yaygın kullanılan bellek teknolojisi hangisidir?', 'SRAM', ['DRAM', 'NAND flash', 'EEPROM'], 'SRAM bilgiyi flip-flop devrelerinde tutar, yenileme gerektirmez ve çok hızlıdır; pahalı ve yer kapladığı için yalnız önbellekte kullanılır.'),
  ('RISC yaklaşımını CISC yaklaşımından ayıran temel tasarım fikri nedir?', 'Az sayıda, basit ve sabit uzunluklu komut kullanmak', ['Tek bir komutla çok sayıda karmaşık bellek işi yapmak', 'Komutları yalnızca ana bellekte yürütmek', 'Yazmaç sayısını en aza indirmek'], 'RISC (Reduced Instruction Set Computer) basit komutlarla her komutu kısa sürede yürütmeyi ve boru hattını verimli kullanmayı hedefler.'),
  ('x86 için derlenmiş bir programın ARM tabanlı bir işlemcide doğrudan çalışamamasının nedeni nedir?', 'İki mimarinin makine kodu komutlarının farklı olması', ['ARM işlemcilerin dosya okuyamaması', 'x86 programlarının her zaman ayrı ekran kartı gerektirmesi', 'ARM işlemcilerin yalnız 8 bit olması'], 'Her mimari kendi makine kodunu anlar; başka bir mimarinin ikili kodu ya yeniden derlenmeli ya da bir çeviri/öykünme katmanıyla çalıştırılmalıdır.'),
  ('32 bitlik bir işlemcinin doğrudan adresleyebileceği en büyük bellek miktarı, bayt adresleme varsayılarak, ne kadardır?', '4 GiB', ['2 GiB', '16 GiB', '32 GiB'], '32 bit ile 2³² = 4.294.967.296 farklı adres oluşur; her adres bir baytı gösterdiğinde bu 4 GiB eder.'),
  ('İşlemcide boru hattı (pipelining) tekniği hangi yolla başarımı artırır?', 'Farklı komutların farklı aşamalarını aynı anda işleyerek', ['Her bir komutun tek başına daha az aşamada bitirilmesiyle', 'Bellek kapasitesinin artırılmasıyla', 'Komutların sırasının rastgele karıştırılmasıyla'], 'Bir komut yürütülürken sonraki çözülür, ondan sonraki getirilir; tek komutun süresi kısalmasa da birim zamanda biten komut sayısı artar.'),
  ('Bilgisayarlarda tek bir hızlı bellek türü yerine katmanlı bir bellek hiyerarşisi kullanılmasının temel nedeni nedir?', 'Hızlı belleklerin pahalı ve küçük, büyük belleklerin ise yavaş olması', ['İşlemcinin tek tür belleği tanıyamaması', 'Yasal düzenlemelerin ve uluslararası standartların bunu zorunlu kılması', 'Hızlı belleğin veri saklayamaması'], 'Hiyerarşi, az miktarda pahalı hızlı belleği bol miktarda ucuz yavaş bellekle birleştirerek hem hızlı hem büyük bir sistem izlenimi verir.'),
  ('Aşağıdaki bellek ya da depolama türlerinden hangisi uçucu değildir (güç kesilince veriyi korur)?', 'NAND flash', ['DRAM', 'SRAM', 'İşlemci yazmacı'], 'Flash bellek yüzer kapılı transistörlerde yükü hapsederek veriyi elektrik olmadan da korur; DRAM, SRAM ve yazmaçlar uçucudur.'),
  ('DRAM\'in düzenli aralıklarla yenilenmesi (refresh) neden gereklidir?', 'Veriyi tutan kondansatörlerdeki yükün zamanla sızması', ['Transistörlerin her okumada yanması', 'Manyetik alanın zayıflaması', 'İşletim sisteminin bunu güvenlik nedeniyle düzenli olarak istemesi'], 'DRAM her biti küçük bir kondansatörde yük olarak tutar; yük sızdığı için hücreler milisaniyeler içinde yeniden yazılmalıdır.'),
  ('SRAM\'in DRAM\'e göre ana bellek olarak kullanılmamasının asıl nedeni nedir?', 'Bit başına daha çok transistör gerektirip pahalı olması', ['DRAM\'den daha yavaş olması', 'Uçucu olmaması', 'Yenileme sırasında içerdiği verinin bir kısmını kaybetmesi'], 'Bir SRAM hücresi genellikle 6 transistör kullanırken DRAM hücresi bir transistör ve bir kondansatörle yetinir; bu yüzden DRAM çok daha yoğun ve ucuzdur.'),
  ('DDR SDRAM\'deki "DDR" (Double Data Rate) ifadesi neyi anlatır?', 'Saatin hem yükselen hem düşen kenarında veri aktarılmasını', ['Bellek modülünün fiziksel olarak iki kat daha büyük olmasını', 'Verinin iki kez yedeklenmesini', 'Belleğin iki işlemciye bağlanmasını'], 'DDR bellek, saatin her iki kenarında veri aktararak aynı saat frekansında tek veri hızlı belleğin iki katı bant genişliği sağlar.'),
  ('Çift kanal destekli bir anakartta 16 GB RAM için hangi seçenek genellikle daha yüksek bellek bant genişliği sağlar?', 'Uygun yuvalara takılmış 2 × 8 GB modül', ['Tek yuvaya takılmış 1 × 16 GB modül', 'İki modülün aynı kanala takılması', 'Modül sayısının bant genişliğine hiçbir etkisi yoktur'], 'Çift kanal modunda iki modüle paralel erişilir ve veri yolu fiilen iki katına çıkar; tek modül bu olanağı kullanamaz.'),
  ('Sunucularda sık kullanılan ECC bellek, sıradan bellekten hangi özelliğiyle ayrılır?', 'Tek bitlik hataları algılayıp düzeltebilmesi', ['Elektrik kesilince veriyi koruması', 'Her zaman daha yüksek bir saat hızında çalışması', 'Yalnızca okunabilmesi'], 'ECC (Error-Correcting Code) bellek fazladan denetim bitleri tutar; tek bitlik hataları düzeltir, çok bitlik hataların bir bölümünü algılar.'),
  ('Dizüstü bilgisayarlarda masaüstüne göre daha küçük boyutlu bellek modülleri kullanılır. Bu modül biçiminin adı nedir?', 'SO-DIMM', ['DIMM', 'SIMM', 'M.2 2280'], 'SO-DIMM (Small Outline DIMM), standart DIMM\'in yaklaşık yarı uzunluğunda olup dizüstü ve küçük kasalı bilgisayarlar için tasarlanmıştır.'),
  ('Bilgisayar açıldığında donanımın çalışıp çalışmadığını denetleyen kısa sınama sürecine ne ad verilir?', 'POST', ['SMART', 'DMA', 'IRQ'], 'POST (Power-On Self-Test), işlemci, bellek ve temel aygıtları denetler; hata olursa çoğu zaman bip sesleriyle bildirir.'),
  ('UEFI\'nin eski BIOS\'a göre getirdiği üstünlüklerden biri hangisidir?', '2 TB\'tan büyük diskleri GPT ile önyükleyebilmesi', ['Yalnızca metin tabanlı arayüz sunması', '16 bit gerçek kipte çalışma zorunluluğu', 'En fazla dört birincil disk bölümüyle sınırlı kalması'], 'UEFI, GPT bölümlendirmesini destekleyerek büyük disklerden önyüklemeye, Güvenli Önyükleme gibi özelliklere ve grafik arayüze olanak tanır.'),
  ('UEFI\'deki Güvenli Önyükleme (Secure Boot) özelliğinin amacı nedir?', 'Yalnız imzalı önyükleyicilerin çalışmasına izin vermek', ['Diskteki tüm verileri şifrelemek', 'Açılış süresini yarıya indirmek', 'Unutulan kullanıcı parolalarını güvenli biçimde sıfırlamak'], 'Güvenli Önyükleme, önyükleme zincirindeki yazılımların imzasını doğrular; imzasız ya da değiştirilmiş önyükleyiciler çalıştırılmaz.'),
  ('EEPROM\'u eski PROM\'dan ayıran temel özellik hangisidir?', 'Elektrikle silinip yeniden programlanabilmesi', ['Yalnızca bir kez yazılabilmesi', 'Morötesi ışıkla silinmesi gerekmesi', 'Güç kesildiğinde içeriğinin tamamını kaybetmesi'], 'PROM bir kez yazılır, EPROM morötesi ışıkla silinir; EEPROM ise elektrik sinyalleriyle silinip yeniden yazılabilir.'),
  ('BIOS/UEFI güncellemesi sırasında elektriğin kesilmesi neden ciddi bir risk sayılır?', 'Yarım kalan yazım anakartı açılmaz hâle getirebilir', ['Sabit diskteki tüm dosyalar kendiliğinden şifrelenir', 'Monitör kalıcı olarak hasar görür', 'İşlemcinin saat hızı sıfıra iner'], 'Güncelleme ürün yazılımı yongasını yeniden yazar; yarıda kalırsa geçerli bir önyükleme kodu kalmayabilir ve kart açılmaz.'),
  ('Bir işlemcinin bir anakarta takılabilmesi için öncelikle hangi uyumun sağlanması gerekir?', 'İşlemcinin anakartın soket türüyle uyumlu olması', ['Kasanın renginin uygun olması', 'Monitörün, klavyenin ve farenin aynı markadan olması', 'RAM\'in işlemciden büyük olması'], 'Her işlemci ailesi belirli bir sokete (ör. LGA ya da AM serisi) uyar; ayrıca yonga seti ve BIOS da o işlemciyi desteklemelidir.'),
  ('Anakart üzerindeki yonga setinin (chipset) temel görevi nedir?', 'İşlemci ile diğer bileşenler arasındaki iletişimi yönetmek', ['Grafik işleri için ayrı bir işlemci gibi çalışıp görüntü üretmek', 'Kalıcı veri depolamak', 'Elektriği alternatif akıma dönüştürmek'], 'Yonga seti USB, SATA, PCIe hatları gibi çevre birimi bağlantılarını işlemciyle konuşturur.'),
  ('Eski anakartlarda kuzey köprüsünün üstlendiği bellek denetleyicisi işlevi modern sistemlerde çoğunlukla nereye taşınmıştır?', 'İşlemcinin kendi yongasına', ['Güç kaynağına', 'Sabit diskin denetleyicisine', 'Ekran kartına'], 'Bellek denetleyicisinin işlemciye taşınması bellek gecikmesini azalttı; kuzey köprüsü bu nedenle ortadan kalktı.'),
  ('Mini-ITX bir anakartın ATX bir anakarta göre tipik kısıtlaması hangisidir?', 'Daha az genişleme yuvası ve bellek yuvası sunması', ['İşlemci takılamaması', 'Üzerinde hiçbir USB bağlantı noktasının bulunmaması', 'Yalnız sabit diskle çalışabilmesi'], 'Mini-ITX yaklaşık 17×17 cm\'dir; genellikle tek PCIe yuvası ve iki bellek yuvası bulunur.'),
  ('Adres yolu genişliğinin artırılması doğrudan neyi etkiler?', 'Adreslenebilecek en büyük bellek miktarını', ['Ekranın renk sayısını', 'Klavyedeki tuş sayısını', 'Güç kaynağının dönüştürme verimliliğini ve gücünü'], 'n hatlı adres yolu 2ⁿ farklı adres üretebilir; dolayısıyla adres yolu genişledikçe erişilebilecek bellek büyür.'),
  ('PCIe yuvalarındaki "×1", "×4", "×16" gösterimleri neyi belirtir?', 'Yuvadaki veri şeridi (lane) sayısını', ['Yuvanın kaçıncı PCIe nesline ait olduğunu', 'Takılabilecek kart sayısını', 'Watt cinsinden güç sınırını'], 'Her şerit ayrı bir gönderme-alma çiftidir; ×16 yuva, ×1 yuvaya göre on altı kat şerit sunar.'),
  ('PCIe 4.0 ×16 destekleyen bir ekran kartı, yalnız PCIe 3.0 ×16 yuvası olan bir anakarta takılırsa ne olur?', 'Kart çalışır, ancak PCIe 3.0 hızıyla sınırlı kalır', ['Kart fiziksel olarak yuvaya girmez', 'Kart hiç çalışmaz', 'Kart anakartı kendiliğinden PCIe 4.0 hızına yükseltir'], 'PCIe geriye dönük uyumludur; bağlantı iki taraftan düşük olan nesilde kurulur.'),
  ('Bir HDD\'nin dakikadaki devir sayısının (RPM) 5400\'den 7200\'e çıkması en çok hangi değeri iyileştirir?', 'Dönme gecikmesini', ['Diskin toplam kapasitesini', 'Arayüzün kuramsal en yüksek hızını', 'Diskin manyetik alana dayanıklılığını'], 'Plaka daha hızlı döndüğü için istenen sektör kafanın altına daha kısa sürede gelir; ortalama dönme gecikmesi azalır.'),
  ('Çalışan bir HDD\'nin sert bir darbe almasının neden olabileceği "kafa çarpması" nedir?', 'Kafanın dönen plakaya değip yüzeyi çizmesi', ['Diskin dosya tablosunun yazılımsal olarak bozulması', 'Kablonun anakarttan kendiliğinden çıkması', 'İşletim sisteminin diski salt okunur kipe alması'], 'Kafa, plakanın nanometrelerce üzerinde süzülür; darbeyle yüzeye temas ederse manyetik katman zarar görür ve veri kaybı olur.'),
  ('HDD\'lerde sık yapılan disk birleştirme (defragmentation) işleminin başarımı artırmasının nedeni nedir?', 'Dosya parçalarını yan yana toplayıp arama süresini kısaltması', ['Diskin dönüş hızını kalıcı olarak artırması', 'Bozuk sektörleri onarıp yeniden kullanılır yapması', 'Dosyaları sıkıştırarak diskte çok daha az yer kaplamalarını sağlaması'], 'Parçalanmış bir dosyayı okumak için kafa birçok yere gitmek zorunda kalır; birleştirme bu arama sürelerini azaltır.'),
  ('Disklerin kendi sağlık durumunu izleyip yeniden atanan sektör sayısı gibi değerleri raporladığı teknoloji hangisidir?', 'S.M.A.R.T.', ['SATA DevSleep', 'AHCI', 'NCQ'], 'S.M.A.R.T. (Self-Monitoring, Analysis and Reporting Technology), arıza belirtilerini önceden sezmek için çeşitli göstergeleri kaydeder.'),
  ('SSD\'lerde kullanılan NAND flash hücreleri için hangi ifade doğrudur?', 'Sınırlı sayıda yazma-silme çevrimine dayanabilirler', ['Sonsuz kez yazılabilir ve hiç yıpranmazlar', 'Güç kesilince içerikleri birkaç saniyede silinir', 'Verileri ancak manyetik bir kafa yardımıyla okunabilir'], 'Her program/silme çevrimi hücrenin yalıtım katmanını biraz yıpratır; bu yüzden SSD\'lerin yazma ömrü TBW gibi değerlerle belirtilir.'),
  ('Bir SSD için klasik disk birleştirme (defrag) işleminin düzenli olarak yapılması neden önerilmez?', 'Kazanç sağlamadan gereksiz yazmalarla hücreleri yıpratır', ['SSD\'deki verilerin tamamen ve kalıcı olarak silinmesine yol açar', 'SSD\'yi işletim sisteminin göremeyeceği biçimde kilitler', 'SSD\'nin dönme hızını düşürüp ısınmasına neden olur'], 'SSD\'de erişim süresi konumdan bağımsızdır; parçaları taşımak yalnızca yazma ömrünü tüketir.'),
  ('NVMe protokolünü kullanan SSD\'ler bilgisayara genellikle hangi arayüz üzerinden bağlanır?', 'PCIe', ['SATA', 'IDE', 'USB 2.0'], 'NVMe, SSD\'lerin düşük gecikme ve yüksek paralellik avantajını kullanmak için PCIe üzerinden çalışacak biçimde tasarlanmıştır.'),
  ('M.2 ifadesi SSD\'lerde neyi tanımlar?', 'Kartın fiziksel biçimini ve bağlantı yuvasını', ['Kullanılan flash hücre türünü ve bit sayısını', 'Diskin en yüksek okuma hızını megabayt cinsinden', 'Diskin desteklediği dosya sistemi türünü'], 'M.2 bir form faktörüdür; bu yuvaya takılan SSD SATA ya da NVMe (PCIe) protokolünü kullanabilir.'),
  ('Blu-ray disklerin DVD\'lerden çok daha fazla veri saklayabilmesinin temel nedeni nedir?', 'Daha kısa dalga boylu mavi-mor lazer kullanılması', ['Disklerin çapının iki kat daha büyük olması', 'Verilerin manyetik bir katmana yazılması', 'Diskin her iki yüzünün de zorunlu olarak kullanılması'], '405 nm\'lik mavi-mor lazer daha küçük bir noktaya odaklanır; böylece çukurlar küçülür ve aynı alana daha çok veri sığar.'),
  ('USB bellek ve SD kart gibi taşınabilir ortamların optik disklerin yerini büyük ölçüde almasının başlıca nedeni hangisidir?', 'Küçük boyutta büyük ve yeniden yazılabilir kapasite sunmaları', ['Lazer ışığına dayanıklı olmaları ve hiç ısınmamaları', 'Veriyi hiçbir koşulda ve hiçbir ortamda kaybetmeyecek biçimde saklamaları', 'Her bilgisayarda yalnızca bir kez kullanılabilmeleri'], 'Flash tabanlı taşınabilir ortamlar küçük, hızlı ve yeniden yazılabilir olup gigabaytlarca kapasite sunar; ayrı bir okuyucu sürücü gerektirmez.'),
  ('Tümleşik (entegre) grafik birimi ile harici ekran kartı arasındaki temel fark hangisidir?', 'Tümleşik birimin sistem RAM\'ini ortak kullanması', ['Tümleşik birimin yalnızca siyah-beyaz görüntü üretebilmesi', 'Harici kartların monitöre bağlanamaması', 'Harici kartların işlemci soketine takılması'], 'Tümleşik grafik işlemciyle aynı yongada ya da yonga setinde bulunur ve ayrı VRAM yerine ana belleği paylaşır; harici kartın kendi belleği vardır.'),
  ('Oyunlarda kullanılan V-Sync (dikey eşitleme) seçeneği hangi sorunu gidermek için geliştirilmiştir?', 'Ekran yırtılması', ['Ölü piksel oluşması', 'Görüntüde renk solması', 'Monitörde arka ışık sızması'], 'GPU, monitör yenilenirken yeni kare gönderirse ekranda iki karenin parçaları üst üste görünür; V-Sync kare gönderimini yenileme anına eşitler.'),
  ('GPU\'ların yalnızca oyunlarda değil, bilimsel hesaplama ve makine öğrenmesinde de yaygın kullanılmasının nedeni hangisidir?', 'Büyük matris işlemlerini paralel yapabilmeleri', ['Metin belgelerini daha hızlı yazdırabilmeleri', 'İnternet bağlantısını daha kararlı hâle getirebilmeleri', 'Sabit diski biçimlendirmeyi hızlandırmaları'], 'Bu alanlardaki hesapların çoğu aynı işlemin büyük veri kümelerine uygulanmasıdır; GPU mimarisi tam da bu tür paralel işe uygundur.'),
  ('3840 × 2160 çözünürlüklü bir ekranda toplam piksel sayısı 1920 × 1080 çözünürlüklü bir ekranın kaç katıdır?', '4', ['2', '8', '16'], 'Her iki boyut da iki katına çıktığı için piksel sayısı 2 × 2 = 4 kat olur (8.294.400 / 2.073.600 = 4).'),
  ('OLED ekranların LCD ekranlara göre çok daha derin siyah gösterebilmesinin nedeni nedir?', 'Her pikselin kendi ışığını üretip kapanabilmesi', ['Arkada çok daha güçlü bir floresan lamba kullanılması', 'Ekran yüzeyinin siyaha boyanmış olması', 'Kristallerin ışığı tamamen geçirmesi'], 'OLED\'de arka ışık yoktur; siyah göstermek için piksel tamamen söner. LCD\'de ise arka ışık hep yanar ve sıvı kristaller ışığı tam kesemez.'),
  ('16:9 en-boy oranına sahip bir ekranın genişliği 32 birim ise yüksekliği kaç birimdir?', '18', ['16', '13,5', '24'], '16:9 oranında genişlik/yükseklik = 16/9 olduğundan yükseklik = 32 × 9 / 16 = 18 birimdir.'),
  ('Bir monitörde yanıt süresinin (response time) düşük olması kullanıcıya hangi yararı sağlar?', 'Hızlı hareketlerde iz ve bulanıklığın azalması', ['Monitörün daha az elektrik tüketerek daha uzun ömürlü olması', 'Ekranın daha geniş açılardan görülebilmesi', 'Desteklenen çözünürlüğün artması'], 'Yanıt süresi pikselin bir renkten diğerine geçme süresidir; kısa olduğunda hareketli nesnelerin arkasında gölge kalmaz.'),
  ('Optik farelerin hareketi algılamak için kullandığı temel yöntem nedir?', 'Yüzeyin görüntüsünü sürekli çekip karşılaştırmak', ['Alttaki lastik topun dönüşünü mekanik olarak ölçmek', 'Fareyi ekrana bağlayan kablonun gerilimini ölçmek', 'Yerçekimi sensörüyle eğimi algılamak'], 'Optik fare LED ya da lazerle yüzeyi aydınlatır, küçük bir sensör saniyede binlerce görüntü alır ve görüntüler arasındaki kaymadan hareketi hesaplar.'),
  ('Akıllı telefonlarda yaygın olan kapasitif dokunmatik ekranın eldivenli elle çoğu zaman çalışmamasının nedeni nedir?', 'Ekranın parmaktaki elektrik yükünü algılaması', ['Ekranın parmağın uyguladığı basıncı ölçerek çalışması', 'Eldivenin ekranın kızılötesi ışığını yansıtması', 'Eldivenin ekranın sıcaklığını düşürmesi'], 'Kapasitif ekran, iletken parmağın yüzeydeki elektrik alanını bozmasını algılar; yalıtkan eldiven bu etkileşimi engeller.'),
  ('Kopyalı (karbonlu) fatura formlarının birden fazla nüshasına aynı anda baskı yapabilen yazıcı türü hangisidir?', 'Nokta vuruşlu yazıcı', ['Lazer yazıcı', 'Mürekkep püskürtmeli yazıcı', 'Sublimasyon (boya buharlaştırmalı) fotoğraf yazıcısı'], 'Nokta vuruşlu yazıcı iğnelerle şeride fiziksel olarak vurur; darbe alttaki nüshalara da geçtiği için kopyalı formlara baskı yapabilir.'),
  ('Ekranlar RGB, yazıcılar ise CMYK renk modelini kullanır. Bu farkın temel nedeni nedir?', 'Ekran ışık yayar, baskı yansıyan ışıkla renk oluşturur', ['Yazıcıların üç renkten fazlasını basmasının yasak olması', 'Kâğıdın ekrandan daha fazla piksel taşıyabilmesi', 'RGB\'nin yalnızca siyah-beyaz görüntülerde kullanılması'], 'Ekran renkleri ışığı toplayarak (eklemeli), mürekkepler ise beyaz ışıktan bazı dalga boylarını soğurarak (çıkarmalı) oluşturur.'),
  ('Eriyik plastik filamenti katman katman yığarak nesne üreten yaygın 3B yazıcı teknolojisinin adı nedir?', 'FDM', ['OLED', 'RAID', 'CMOS'], 'FDM (Fused Deposition Modeling) yönteminde ısıtılmış nozul filamenti eritip katmanlar hâlinde biriktirir.'),
  ('USB 2.0\'ın kuramsal en yüksek veri aktarım hızı ne kadardır?', '480 Mbit/s', ['12 Mbit/s', '5 Gbit/s', '10 Gbit/s'], 'USB 2.0 (High Speed) 480 Mbit/s, USB 3.0 (SuperSpeed) 5 Gbit/s hızındadır; 12 Mbit/s ise USB 1.1\'in tam hızıdır.'),
  ('Bilgisayar monitörlerinde HDMI\'ye alternatif olarak yaygın kullanılan, VESA tarafından geliştirilmiş sayısal görüntü arayüzü hangisidir?', 'DisplayPort', ['FireWire', 'S-Video', 'SCART'], 'DisplayPort, VESA\'nın geliştirdiği ve özellikle bilgisayar monitörlerinde yüksek çözünürlük ve yenileme hızı için kullanılan arayüzdür.'),
  ('Eski VGA bağlantısı ile HDMI arasındaki temel teknik fark hangisidir?', 'VGA analog, HDMI sayısal sinyal taşır', ['VGA sayısal, HDMI ise analog sinyal taşıyan bir arayüzdür', 'İkisi de yalnızca ses sinyali taşır', 'VGA kablosuz, HDMI ise kablolu bir bağlantıdır'], 'VGA renk bileşenlerini analog gerilimler olarak iletir; HDMI ise görüntüyü sayısal veri olarak gönderir, bu yüzden dönüşüm kaybı yaşanmaz.'),
  ('Güç kaynaklarındaki "80 PLUS Gold" gibi sertifikalar neyi gösterir?', 'Enerji dönüşüm verimliliğinin düzeyini', ['Güç kaynağının en yüksek watt değerini', 'Kaynağın kaç yıl garanti altında olduğunu', 'Fanın çıkardığı ses düzeyini desibel cinsinden'], '80 PLUS sertifikaları belirli yük düzeylerinde AC\'den DC\'ye dönüşümde ne kadar enerjinin ısı olarak kaybolmadığını derecelendirir.'),
  ('İşlemci ile soğutucu arasına sürülen termal macunun görevi nedir?', 'Yüzeyler arasındaki hava boşluklarını doldurup ısı iletimini artırmak', ['İşlemciyi sokete elektriksel olarak bağlamak', 'Soğutucunun fanını yağlamak', 'İşlemciyi tozdan, nemden ve darbelerden yalıtarak tamamen korumak'], 'Metal yüzeylerdeki mikroskobik pürüzler ısıyı kötü ileten hava hapseder; termal macun bu boşlukları doldurur.'),
  ('Aşırı ısınan bir işlemcinin kendini korumak için saat hızını otomatik olarak düşürmesine ne ad verilir?', 'Termal kısma (thermal throttling)', ['Hız aşırtma (overclocking)', 'Gerilim yükseltme (overvolting)', 'Önbellek boşaltma (cache flush) işlemi'], 'Sıcaklık sınırı aşıldığında işlemci frekansını ve gerilimini düşürerek ısı üretimini azaltır; bu da başarımın geçici olarak düşmesine yol açar.'),
  ('Sıvı soğutma sistemlerinde ısı işlemciden ortama hangi yolla aktarılır?', 'Pompalanan sıvı ısıyı radyatöre taşır, fanlar havaya verir', ['Sıvı işlemcinin yüzeyine doğrudan püskürtülüp buharlaştırılır', 'Isı elektrik enerjisine dönüştürülerek prize geri verilir', 'Sıvı işlemcinin içinden geçerek transistörleri soğutur'], 'Soğutma bloğundaki sıvı ısıyı alır, pompa onu radyatöre taşır; radyatördeki fanlar ısıyı kasa dışına atar.'),
  ('Onaltılık tabanda yazılan 2F sayısı onluk tabanda neye eşittir?', '47', ['32', '215', '45'], '2F₁₆ = 2 × 16 + 15 = 47; onaltılıkta F harfi 15 değerini gösterir.'),
  ('Bellek adresleri ve renk kodları gibi ikilik değerlerin çoğu zaman onaltılık tabanda yazılmasının nedeni nedir?', 'Her onaltılık basamağın tam olarak 4 bite karşılık gelmesi', ['Onaltılık sayıların bilgisayarda daha az elektrik harcaması', 'Onluk tabanın bilgisayarlar tarafından hiç anlaşılmaması', 'Onaltılık sistemin yalnızca harflerden oluşması'], '16 = 2⁴ olduğundan her onaltılık rakam dört bitlik bir gruba denk gelir; uzun ikilik diziler kısa ve okunaklı yazılır.'),
  ('11010110 ikilik sayısının onaltılık karşılığı nedir?', 'D6', ['C6', 'D3', '6D'], 'Dörtlü gruplara ayrılır: 1101 = D, 0110 = 6; sonuç D6₁₆ olur.'),
  ('8 bitlik işaretsiz bir yazmaçta 255 değeri tutulurken bu değere 1 eklenirse yazmaçta hangi değer kalır?', '0', ['256', '255', '128'], '8 bit en çok 255 (11111111) tutar; 1 eklenince sonuç 1 0000 0000 olur ve dokuzuncu bit sığmadığından yazmaçta 0 kalır (taşma).'),
  ('İkilik tabanda 1100 ve 1010 sayıları bit düzeyinde VE (AND) işlemine sokulursa sonuç onluk tabanda kaçtır?', '8', ['14', '6', '2'], 'Bit bit VE: 1100 AND 1010 = 1000₂ = 8; yalnız iki sayıda da 1 olan bitler 1 kalır.'),
  ('Ambalajında "500 GB" yazan bir disk, işletim sisteminde yaklaşık 465 GB olarak görünüyor. Bu farkın nedeni nedir?', 'Üretici 10\'un, işletim sistemi 2\'nin kuvvetleriyle hesaplar', ['Diskin 35 GB\'lık bölümünün fabrikada bozuk çıkması', 'İşletim sisteminin diskin bir kısmını gizlice sıkıştırması', 'Diskin ilk açılışta kendini biçimlendirip kalıcı olarak küçültmesi'], '500 GB = 500×10⁹ bayttır; bu sayı 2³⁰\'a bölünürse ≈ 465,7 GiB çıkar. Windows bu değeri "GB" etiketiyle gösterir.'),
  ('Piksel başına 24 bit renk derinliği kullanan bir sistemde kaç farklı renk gösterilebilir?', '16.777.216', ['65.536', '16.581.375', '4.294.967.296'], '24 bit ile 2²⁴ = 16.777.216 renk elde edilir; her biri 8 bitlik kırmızı, yeşil ve mavi kanal 256 düzey sunar.'),
  ('Bir SSD\'nin aktarım hızı bit cinsinden 800 Mbps olarak verilmiştir. Bu hız bayt cinsinden kaç MB/s eder?', '100 MB/s', ['800 MB/s', '6400 MB/s', '80 MB/s'], 'Bir bayt 8 bit olduğundan 800 Mbit/s ÷ 8 = 100 MB/s.'),
  ('İki girişli ÖZEL VEYA (XOR) kapısı hangi durumda 1 çıkışı verir?', 'Girişler birbirinden farklı olduğunda', ['İki giriş de 1 olduğunda ve yalnızca o zaman', 'İki giriş de 0 olduğunda', 'Girişlerden en az biri 0 olduğunda'], 'XOR, girişlerden yalnız biri 1 iken 1 verir; 0-0 ve 1-1 durumlarında çıkış 0 olur.'),
  ('A = 1, B = 0 ve C = 1 iken (A VE B) VEYA C ifadesinin değeri nedir?', '1', ['0', '2', 'Tanımsız'], 'A VE B = 1 VE 0 = 0; ardından 0 VEYA 1 = 1 olur.'),
  ('De Morgan kurallarına göre DEĞİL(A VE B) ifadesi hangisine eşittir?', '(DEĞİL A) VEYA (DEĞİL B)', ['(DEĞİL A) VE (DEĞİL B)', 'A VEYA B', 'DEĞİL(A VEYA B)'], 'De Morgan: ¬(A ∧ B) = ¬A ∨ ¬B; bir VE ifadesinin değili, değillerin VEYA\'sına eşittir.'),
  ('Üç girişli bir mantık devresinin doğruluk tablosunda kaç satır bulunur?', '8', ['6', '9', '3'], 'Her giriş 0 ya da 1 olabilir; üç giriş için 2³ = 8 farklı birleşim vardır.'),
  ('Standart ASCII kodlaması her karakter için kaç bit kullanır?', '7', ['8', '16', '32'], 'Standart ASCII 7 bitlik bir koddur ve 128 karakter tanımlar; 8 bitlik türevlere "genişletilmiş ASCII" denir.'),
  ('Türkçe "ğ, ş, ı" gibi harflerin standart ASCII ile gösterilememesinin nedeni nedir?', 'ASCII\'nin yalnızca 128 karakterlik bir küme tanımlaması', ['Bu harflerin bilgisayar klavyelerinde fiziksel olarak bulunmaması', 'ASCII\'nin yalnız rakamları kodlayabilmesi', 'Türkçe harflerin ikilik tabanda yazılamaması'], 'ASCII İngiliz alfabesi, rakamlar, noktalama ve denetim karakterleriyle sınırlıdır; Türkçe harfler için Unicode gibi daha geniş kodlamalar gerekir.'),
  ('ASCII tablosunda büyük "A" harfinin kodu 65\'tir. Büyük "E" harfinin kodu nedir?', '69', ['68', '70', '101'], 'Harfler ardışık kodlanmıştır: A=65, B=66, C=67, D=68, E=69. (101 küçük "e" harfinin kodudur.)'),
  ('"Von Neumann darboğazı" olarak bilinen sorun neyi anlatır?', 'İşlemcinin ortak bellek yolunu beklerken yavaşlamasını', ['Programların bellekte tutulamamasını', 'Bilgisayarın birden fazla programı hiç çalıştıramamasını', 'Sabit disk kapasitesinin sınırlı olmasını'], 'Komut ve veri aynı yoldan geldiği için hızlı işlemci, görece yavaş bellek aktarımını beklemek zorunda kalır; önbellekler bu sorunu hafifletir.'),
  ('Harvard mimarisini Von Neumann mimarisinden ayıran temel özellik nedir?', 'Komut ve veri için ayrı bellek ve yolların kullanılması', ['Bilgisayarın hiçbir belleğe sahip olmaması', 'Programların yalnızca delikli kartlardan okunabilir olması', 'İşlemcinin tek bir yazmaçla çalışması'], 'Harvard mimarisinde komut ve veri ayrı yollardan eşzamanlı okunabilir; bu tasarım özellikle mikrodenetleyicilerde ve DSP\'lerde yaygındır.'),
  ('Bir kelime işlemci programı yazıcıya çıktı gönderirken yazıcının iç ayrıntılarını bilmek zorunda değildir. Bunu sağlayan, işletim sisteminin hangi rolüdür?', 'Donanımı soyutlaması', ['Dosyaları sıkıştırması', 'Kullanıcı parolalarını saklaması', 'Ekran koruyucusunu çalıştırması'], 'İşletim sistemi sürücüler aracılığıyla donanım ayrıntılarını gizler ve uygulamalara standart bir yazdırma arayüzü sunar.'),
  ('Çok görevli (multitasking) bir işletim sisteminde tek çekirdekli bir işlemci birden çok programı "aynı anda" çalıştırıyormuş gibi görünür. Bu nasıl sağlanır?', 'İşlemci süresi küçük dilimlerle programlar arasında paylaştırılır', ['Her program kendisine ayrılmış ayrı bir fiziksel işlemcide çalıştırılır', 'Programlar tek bir büyük program hâlinde birleştirilir', 'Programlar yalnızca RAM\'de bekletilip hiç çalıştırılmaz'], 'Zaman paylaşımı sayesinde işletim sistemi milisaniyelik dilimlerle programlar arasında hızla geçiş yapar; kullanıcıya hepsi eşzamanlı çalışıyor gibi görünür.'),
  ('Bir uygulamanın dosya açmak gibi işler için çekirdekten hizmet istemesine ne ad verilir?', 'Sistem çağrısı', ['Önbellek ıskalaması', 'Sayfa değişimi', 'Güç döngüsü'], 'Sistem çağrısı (system call), kullanıcı kipindeki programın çekirdeğin ayrıcalıklı hizmetlerine denetimli biçimde erişmesini sağlayan arayüzdür.'),
  ('Linux\'ta bir aygıt sürücüsünün sistemi yeniden başlatmadan çekirdeğe eklenebilmesini sağlayan yapı hangisidir?', 'Yüklenebilir çekirdek modülleri', ['Toplu iş dosyaları', 'Windows kayıt defteri anahtarları', 'Masaüstü kısayolları'], 'Linux monolitik olmasına karşın çalışma sırasında modül (.ko dosyaları) yükleyip kaldırabilir; modprobe gibi araçlar bu işi yapar.'),
  ('Bir uygulamanın çökmesinin genellikle tüm işletim sistemini çökertmemesi hangi tasarım özelliğinin sonucudur?', 'Süreçlerin ayrı bellek alanlarında yalıtılması', ['Uygulamaların her zaman sabit diskte çalıştırılması', 'İşlemcinin yalnızca bir program çalıştırabilmesi', 'Ekran kartının hataları otomatik düzeltmesi'], 'Her sürecin kendi sanal adres alanı vardır; bir süreç başka bir sürecin ya da çekirdeğin belleğine yazamaz, bu yüzden hata yalıtılır.'),
  ('Aynı sürece ait iş parçacıklarının (thread) ortak kullandığı kaynak hangisidir?', 'Sürecin bellek adres alanı', ['Her birinin ayrı program sayacı', 'Her birinin ayrı yığın (stack) bölgesi', 'Her birinin ayrı yazmaç kümesi'], 'İş parçacıkları kod, veri ve açık dosyaları paylaşır; ancak her birinin kendi program sayacı, yazmaçları ve yığını vardır.'),
  ('Diskten veri okumayı bekleyen bir süreç, veri geldiğinde doğrudan hangi duruma geçer?', 'Hazır durumuna', ['Çalışıyor durumuna', 'Sonlandı durumuna', 'Yeni (new) durumuna'], 'G/Ç tamamlanınca süreç bekleme durumundan hazır kuyruğuna geçer; işlemciyi ancak zamanlayıcı seçtiğinde alır.'),
  ('İşletim sisteminin her süreç için tuttuğu; süreç kimliği, durumu ve yazmaç değerlerini içeren veri yapısına ne denir?', 'Süreç denetim bloğu (PCB)', ['Dosya ayırma tablosu (FAT)', 'Ana önyükleme kaydı (MBR)', 'Kesme vektör tablosu'], 'PCB, bir sürecin işletim sistemi gözündeki kimlik kartıdır; bağlam değiştirmede yazmaç değerleri buraya kaydedilir.'),
  ('Unix benzeri sistemlerde fork() sistem çağrısı ne yapar?', 'Çağıran sürecin bir kopyası olan yeni bir alt süreç oluşturur', ['Çalışan süreci kalıcı olarak sonlandırıp belleğini serbest bırakır', 'Bir dosyayı iki ayrı dizine böler', 'İşlemcinin saat hızını iki katına çıkarır'], 'fork() sonrasında ana ve alt süreç aynı noktadan çalışmaya devam eder; dönüş değeri alt süreçte 0, ana süreçte alt sürecin kimliğidir.'),
  ('Ana süreci sonlandığı hâlde çalışmaya devam eden bir alt sürece Unix sistemlerinde ne ad verilir?', 'Yetim (orphan) süreç', ['Zombi (defunct) süreç', 'Çekirdek süreci', 'Kilitli süreç'], 'Yetim süreçler init (ya da systemd) tarafından sahiplenilir; zombi süreç ise sonlanmış ama çıkış durumu henüz ana süreçce okunmamış süreçtir.'),
  ('Döngüsel (round robin) zamanlamada zaman diliminin (quantum) çok küçük seçilmesinin olumsuz sonucu nedir?', 'Bağlam değiştirme yükünün artması', ['Uzun süreçlerin hiç çalışamaması', 'Algoritmanın FCFS\'ye dönüşmesi', 'Belleğin hızla tükenip sistemin kilitlenmesi'], 'Her dilim sonunda bağlam değiştirilir; dilim küçüldükçe işlemci zamanının giderek büyük bir kısmı geçişlere harcanır.'),
  ('Kesintili (preemptive) zamanlamayı kesintisiz zamanlamadan ayıran özellik nedir?', 'İşletim sisteminin çalışan süreci zorla durdurabilmesi', ['Süreçlerin hiçbir zaman bitmeden sonsuza dek çalışmaya devam etmesi', 'Yalnızca tek bir sürecin çalıştırılabilmesi', 'Süreçlerin yalnızca kullanıcı onayıyla başlatılması'], 'Kesintili zamanlamada zamanlayıcı kesmesi ya da daha öncelikli bir sürecin gelişi çalışan süreci hazır kuyruğuna geri gönderebilir.'),
  ('İki iş parçacığı aynı sayaç değişkenini eşzamanlı olarak artırıyor ve son değer bazen beklenenden küçük çıkıyor. Bu hatanın adı nedir?', 'Yarış durumu (race condition)', ['Kilitlenme', 'Açlık', 'Bellek sızıntısı (memory leak)'], '"Oku–artır–yaz" adımları bölünemez değildir; iki iş parçacığı aynı eski değeri okuyup yazarsa bir artış kaybolur.'),
  ('Paylaşılan bir veriye aynı anda yalnızca tek bir iş parçacığının erişmesini sağlamak için kullanılan eşzamanlama aracı hangisidir?', 'Muteks', ['Önbellek satırı (cache line) kilidi', 'Kesme vektörü', 'Bölüm tablosu'], 'Muteksi alan iş parçacığı kritik bölgeye girer; diğerleri kilit serbest bırakılana kadar bekler.'),
  ('Bütün süreçlerin kaynakları her zaman aynı genel sırayla (önce A, sonra B) istemesi zorunlu tutulursa hangi sorun önlenmiş olur?', 'Döngüsel beklemeye dayalı kilitlenme', ['Bellek parçalanması', 'Önbellek ıskalamalarının artması ve sistemin yavaşlaması', 'Ekran yırtılması'], 'Kaynaklar tek bir sırayla istenince A\'yı tutup B\'yi bekleyen bir süreç ile B\'yi tutup A\'yı bekleyen başka bir süreç oluşamaz; döngüsel bekleme koşulu bozulur.'),
  ('Sanal bellek tekniği bir bilgisayara hangi olanağı sağlar?', 'Programların fiziksel RAM\'den büyük adres alanı kullanması', ['RAM\'in elektrik kesildiğinde de verilerini kalıcı olarak tutabilmesi', 'İşlemcinin saat hızının kendiliğinden artması', 'Sabit diskin RAM\'den daha hızlı çalışması'], 'Sanal bellek, her sürece geniş bir mantıksal adres alanı verir; o anda kullanılmayan sayfalar diskte tutulup gerektiğinde RAM\'e getirilir.'),
  ('Sanal adresleri fiziksel adreslere çeviren donanım birimine ne ad verilir?', 'MMU (bellek yönetim birimi)', ['ALU (aritmetik mantık birimi)', 'PSU (güç kaynağı birimi)', 'DMA denetleyicisi'], 'MMU, sayfa tablolarını kullanarak her bellek erişiminde sanal adresi fiziksel adrese dönüştürür ve erişim izinlerini denetler.'),
  ('Bir sürecin RAM\'de bulunmayan bir sayfaya erişmeye çalışması sonucunda oluşan olaya ne ad verilir?', 'Sayfa hatası (page fault)', ['Çekirdek paniği', 'Önbellek isabeti', 'Yığın taşması (stack overflow)'], 'Sayfa hatasında işletim sistemi devreye girer, istenen sayfayı diskten RAM\'e yükler ve süreci kaldığı yerden sürdürür.'),
  ('Birçok sekme ve programla çalışırken bilgisayarı sürekli disk etkinliğiyle yavaşlayan bir kullanıcıya en etkili donanım önerisi hangisidir?', 'RAM miktarını artırmak', ['Daha büyük bir monitör almak', 'Daha hızlı bir fare kullanmak', 'Güç kaynağını daha yüksek wattlı bir modelle değiştirmek'], 'Sürekli disk etkinliği RAM yetmediği için takas alanının kullanıldığını gösterir; daha fazla RAM sayfa değişimlerini azaltır.'),
  ('Sanal adres çevirilerini hızlandırmak için son kullanılan sayfa tablosu girişlerini saklayan özel önbellek hangisidir?', 'TLB', ['BIOS', 'VRAM', 'RAID'], 'TLB (Translation Lookaside Buffer), MMU içinde bulunur; isabet olursa sayfa tablosuna bellekten bakmaya gerek kalmaz.'),
  ('Bir programın ayırdığı belleği işi bittiği hâlde geri vermemesi ve zamanla bellek kullanımının sürekli artmasına ne ad verilir?', 'Bellek sızıntısı', ['Sayfa hatası', 'Bağlam değiştirme', 'Önbellek tutarlılığı'], 'Bellek sızıntısında serbest bırakılmayan bellek bloğu birikir; uzun süre çalışan programlarda sistem belleği tükenebilir.'),
  ('FAT32 biçimli bir USB belleğe 6 GB\'lık bir video dosyası kopyalanamıyor. Bunun nedeni nedir?', 'FAT32\'de tek dosyanın 4 GB\'tan büyük olamaması', ['USB belleklerin en çok 4 GB kapasiteli olabilmesi', 'Video dosyalarının yalnızca optik disklere yazılabilmesi', 'FAT32\'nin yalnızca metin dosyalarını desteklemesi'], 'FAT32 dosya boyutunu 32 bitlik alanda tuttuğu için en büyük dosya 4 GiB − 1 bayttır; daha büyük dosyalar için exFAT ya da NTFS gerekir.'),
  ('Apple\'ın 2017\'den itibaren macOS ve iOS aygıtlarında kullandığı, SSD\'ler için iyileştirilmiş dosya sistemi hangisidir?', 'APFS', ['HFS Plus', 'ReFS', 'XFS'], 'APFS (Apple File System), anlık görüntü, klonlama ve güçlü şifreleme desteği sunar; HFS+\'ın yerini almıştır.'),
  ('Hem Windows hem macOS bilgisayarlarda okunup yazılacak, 4 GB\'tan büyük dosyalar taşıyacak bir harici disk için en uygun dosya sistemi hangisidir?', 'exFAT', ['FAT32', 'ext4', 'APFS'], 'exFAT her iki sistemde de yerleşik olarak desteklenir ve FAT32\'nin 4 GB dosya sınırını taşımaz; ext4 ve APFS ise öteki sistemde ek yazılım gerektirir.'),
  ('Bir diski "hızlı biçimlendirme" seçeneğiyle biçimlendirmek için hangi ifade doğrudur?', 'Yeni yapılar yazılır, eski veriler hemen fiziksel olarak silinmez', ['Diskteki her sektör sıfırlarla doldurularak veriler kalıcı biçimde yok edilir', 'Diskin dönüş hızı düşürülür', 'Diskin kapasitesi iki katına çıkar'], 'Hızlı biçimlendirme yalnız dosya tablosunu ve yapıları yeniden oluşturur; eski veriler üzerine yazılana kadar kurtarma araçlarıyla bulunabilir.'),
  ('Eski MBR bölümlendirme şemasında bir diskte en fazla kaç birincil bölüm oluşturulabilir?', '4', ['2', '8', '128'], 'MBR\'deki bölüm tablosu dört girişlidir; daha fazla bölüm için bir genişletilmiş bölüm ve onun içinde mantıksal bölümler kullanılır.'),
  ('GPT bölümlendirme şemasının MBR\'ye göre üstünlüklerinden biri hangisidir?', 'Bölüm tablosunun yedeğini diskin sonunda tutması', ['Yalnızca eski 16 bitlik işlemcilerle uyumlu olması', 'En çok iki bölüme izin vermesi', 'Disk kapasitesini 2 GB ile sınırlaması'], 'GPT, birincil başlığını diskin başında, yedek başlığını sonunda saklar ve CRC denetimiyle bozulmayı fark edebilir; Windows\'ta 128 bölüme kadar destek verir.'),
  ('Bir kullanıcı işletim sistemini ve kişisel dosyalarını aynı diskin iki ayrı bölümünde tutuyor. Bu düzenin en önemli yararı hangisidir?', 'Sistem yeniden kurulurken kişisel bölüm korunabilir', ['Disk kapasitesinin kendiliğinden ve kalıcı olarak iki katına çıkması', 'Diskin hiçbir zaman arızalanmayacak hâle gelmesi', 'İşlemcinin daha hızlı çalışması'], 'Sistem bölümü biçimlendirilip işletim sistemi yeniden kurulduğunda öteki bölümdeki veriler dokunulmadan kalır; ancak bu bir yedek yerine geçmez.'),
  ('UEFI ile önyüklenen bir bilgisayarda önyükleyici dosyalarının bulunduğu, FAT32 ile biçimlendirilmiş özel bölümün adı nedir?', 'EFI sistem bölümü (ESP)', ['Takas bölümü (Linux swap)', 'Kurtarma bölümü', 'Genişletilmiş bölüm'], 'UEFI ürün yazılımı FAT dosya sistemini okuyabilir; ESP\'deki .efi dosyalarını bulup çalıştırarak önyüklemeyi başlatır.'),
  ('Bilgisayar açılırken aşağıdaki olaylardan hangisi ilk gerçekleşir?', 'Ürün yazılımının POST sınaması', ['Çekirdeğin belleğe yüklenmesi', 'Kullanıcı giriş ekranının açılması', 'Arka plan hizmetlerinin başlatılması'], 'Sıra genellikle şöyledir: ürün yazılımı ve POST, önyükleyici, çekirdek, ilk süreç (init/systemd ya da Windows oturum yöneticisi), giriş ekranı.'),
  ('Bir bilgisayarın USB bellekteki kurulum ortamından açılması isteniyorsa hangi ayarın değiştirilmesi gerekir?', 'Ürün yazılımındaki önyükleme sırası', ['Ekran çözünürlüğü ayarı', 'İşletim sisteminin saat dilimi ve bölge ayarı', 'Fare imlecinin hızı'], 'BIOS/UEFI\'deki önyükleme sırası, ürün yazılımının önyüklenebilir aygıtları hangi sırayla deneyeceğini belirler.'),
  ('"Uyku" ile "hazırda bekletme" kipleri arasındaki temel fark nedir?', 'Uykuda durum RAM\'de, hazırda bekletmede diskte tutulur', ['Uykuda bilgisayar tamamen kapanır, hazırda bekletmede ekran açık kalır', 'İkisinde de tüm veriler silinir', 'Hazırda bekletme yalnızca masaüstü bilgisayarlarda bulunan bir kiptir'], 'Uyku kipinde RAM\'e düşük güç verilmeye devam eder; hazırda bekletmede RAM içeriği diske yazılır ve bilgisayar güç harcamadan bekler.'),
  ('Bir aygıtı bilgisayar çalışırken takıp çıkarabilme ve sistemin onu kendiliğinden tanıması özelliğine ne ad verilir?', 'Tak ve çalıştır / sıcak takma', ['Hız aşırtma ve gerilim düşürme', 'Önbellek boşaltma', 'Disk bölümlendirme'], 'USB gibi arayüzler sıcak takmayı (hot-plug) destekler; işletim sistemi aygıtı algılayıp uygun sürücüyü kendiliğinden yükler.'),
  ('Windows\'ta sistem ve uygulama ayarlarının hiyerarşik olarak saklandığı merkezî veritabanına ne ad verilir?', 'Kayıt Defteri', ['Olay Görüntüleyicisi günlüğü', 'Geri Dönüşüm Kutusu', 'Görev Zamanlayıcısı'], 'Kayıt Defteri HKEY_LOCAL_MACHINE gibi kök anahtarlar altında yapılandırma bilgilerini tutar; regedit ile düzenlenebilir.'),
  ('Windows\'ta PowerShell\'in klasik Komut İstemi\'nden (cmd) ayrılan temel özelliği nedir?', 'Komutlar arasında metin yerine nesne aktarması', ['Yalnızca grafik arayüzle kullanılabilmesi', 'Hiçbir betik dosyasını çalıştıramaması', 'Yalnızca Linux ve macOS sistemlerinde çalışabilmesi'], 'PowerShell .NET tabanlıdır; cmdlet\'ler birbirine yapılandırılmış nesneler aktarır, bu da karmaşık yönetim işlerini kolaylaştırır.'),
  ('Linux dosya sisteminde sistem genelindeki yapılandırma dosyaları geleneksel olarak hangi dizinde bulunur?', '/etc', ['/home', '/tmp', '/boot'], '/etc yapılandırma dosyalarını, /home kullanıcı dizinlerini, /tmp geçici dosyaları, /boot önyükleme dosyalarını barındırır.'),
  ('Linux\'ta "Belge.txt" ve "belge.txt" adlı iki dosya aynı dizinde bulunabilir. Bunun nedeni nedir?', 'Dosya sistemlerinin büyük-küçük harfe duyarlı olması', ['Linux\'un dosya uzantılarını hiç tanımaması', 'İkinci dosyanın gizli dosya sayılması', 'Linux\'un her dosyayı kendine ait ayrı bir diskte saklaması'], 'ext4 gibi dosya sistemlerinde harf büyüklüğü adın bir parçasıdır; bu iki ad farklı dosyaları gösterir.'),
  ('Ubuntu, Fedora ve Debian gibi adlar Linux dünyasında neyi ifade eder?', 'Linux çekirdeği üzerine kurulu dağıtımları', ['Farklı işlemci mimarilerini ve komut kümelerini', 'Linux\'un dosya sistemlerini', 'Komut satırı kabuklarını'], 'Dağıtımlar Linux çekirdeğini sistem araçları, paket yöneticisi ve masaüstü ortamıyla bir araya getirerek tam işletim sistemi oluşturur.'),
  ('C programlama dilinin geliştirilmesi en çok hangi işletim sisteminin yazılmasıyla ilişkilidir?', 'Unix', ['MS-DOS', 'Windows', 'Android'], 'Dennis Ritchie C dilini Bell Laboratuvarları\'nda geliştirdi; Unix\'in büyük bölümü 1973\'te C ile yeniden yazıldı ve bu, sistemin taşınabilirliğini sağladı.'),
  ('macOS\'un temelinde bulunan ve Unix uyumlu çekirdek ile alt sistemleri içeren açık kaynaklı katman hangisidir?', 'Darwin', ['Aqua', 'Cocoa', 'Carbon API'], 'Darwin, XNU çekirdeğini ve BSD bileşenlerini içerir; macOS bu sayede POSIX uyumlu bir Unix sistemidir.'),
  ('macOS\'ta uygulamalar Finder\'da tek bir simge gibi görünse de aslında hangi biçimde paketlenmiştir?', '.app uzantılı özel klasörler', ['Tek parça .exe dosyaları', 'Sıkıştırılmış .zip arşivleri olarak', 'Disk görüntüsü olan .iso dosyaları'], '.app paketleri, çalıştırılabilir dosya ile kaynakları içeren bir klasör yapısıdır; Finder bunları tek bir öğe olarak gösterir.'),
  ('Mobil işletim sistemlerinde uygulamaların birbirinin verisine doğrudan erişememesini sağlayan yaklaşıma ne ad verilir?', 'Kum havuzu', ['Önbellek tutarlılığı ilkesi', 'Disk bölümlendirme yöntemi', 'Çok kanallı bellek'], 'Her uygulama kendine ayrılmış yalıtılmış bir alanda çalışır; başka uygulamaların dosyalarına ya da sistem kaynaklarına ancak verilen izinlerle erişebilir.'),
  ('Mobil işletim sistemlerinin arka planda kalan uygulamaları sık sık askıya alması ya da kapatmasının başlıca nedeni nedir?', 'Pil ömrünü ve sınırlı RAM\'i korumak', ['Uygulamaların lisans süresini denetlemek', 'Ekran çözünürlüğünü yükseltmek ve renkleri canlandırmak', 'İnternet tarifesini değiştirmek'], 'Telefonlarda enerji ve bellek kısıtlıdır; görünmeyen uygulamaların işlemciyi ve belleği kullanması engellenerek pil ve yanıt hızı korunur.'),
  ('Linux\'ta "echo Merhaba > not.txt" komutu ne yapar?', '"Merhaba" yazısını not.txt\'ye yazar, varsa üzerine yazar', ['not.txt dosyasının içeriğini ekranda gösterir', 'not.txt dosyasını Merhaba adlı yeni bir dizine taşır', '"Merhaba" yazısını dosyanın sonuna ekler, eski içeriği hiç bozmaz'], '">" çıktıyı dosyaya yönlendirir ve dosyayı baştan yazar; sona eklemek için ">>" kullanılır.'),
  ('Linux\'ta "chmod 755 betik.sh" komutundan sonra dosyanın izinleri hangisi olur?', 'rwxr-xr-x', ['rwxrwxrwx', 'rw-r--r--', 'rwx------'], '7 = 4+2+1 (rwx), 5 = 4+1 (r-x); sahip tüm izinlere, grup ve diğerleri okuma ve çalıştırma iznine sahip olur.'),
  ('Linux\'ta izinleri 644 olan bir metin dosyasını grup üyesi olmayan başka bir kullanıcı ne yapabilir?', 'Yalnızca okuyabilir', ['Okuyup değiştirebilir', 'Okuyup çalıştırabilir', 'Hiçbir biçimde açamaz'], '644 = rw-r--r--; son basamak 4, "diğerleri"ne yalnız okuma izni verir.'),
  ('Linux\'ta dosyanın sahibini değiştirmek için hangi komut kullanılır?', 'chown', ['chmod', 'chdir', 'chroot'], 'chown (change owner) sahibi ve grubu değiştirir; chmod ise izin bitlerini değiştirir.'),
  ('Windows\'ta bir programın sistem ayarlarını değiştirmeden önce ekranın kararıp onay istenmesi hangi özelliğin işidir?', 'Kullanıcı Hesabı Denetimi', ['Görev Yöneticisi\'nin süreç izleme sekmesi', 'Disk Temizleme', 'Ekran koruyucu'], 'UAC, yönetici hesabıyla bile çalışırken uygulamaları standart yetkiyle başlatır; yükseltilmiş yetki gerektiğinde açıkça onay ister.'),
  ('Bir ailede herkesin aynı bilgisayarı kullandığı durumda her bireye ayrı kullanıcı hesabı açmanın en önemli yararı hangisidir?', 'Herkesin dosya ve ayarlarının ayrı tutulması', ['Bilgisayarın her hesap için ayrı işlemci kullanması', 'Disk kapasitesinin hesap sayısı kadar artması', 'Elektrik tüketiminin azalması'], 'Her hesabın kendi ev klasörü, masaüstü ve ayarları olur; izinler sayesinde başkalarının dosyalarına izinsiz erişilemez.'),
  ('Sanal makineleri oluşturup çalıştıran ve donanım kaynaklarını onlara paylaştıran yazılıma ne denir?', 'Hiper yönetici (hypervisor)', ['Derleyici (compiler)', 'Önyükleyici (bootloader)', 'Sürücü yöneticisi (driver manager)'], 'Hiper yönetici, fiziksel kaynakları sanal makineler arasında bölüştürür ve onları birbirinden yalıtır.'),
  ('Sanal makinelerde alınan "anlık görüntü" (snapshot) özelliği ne işe yarar?', 'Makinenin o anki durumuna sonradan geri dönmeyi sağlar', ['Sanal makinenin ekran görüntüsünü resim olarak kaydeder', 'Sanal makineyi daha hızlı çalıştırır', 'Ana bilgisayarın işletim sistemini günceller'], 'Anlık görüntü disk ve bellek durumunu kaydeder; riskli bir değişiklikten sonra makine bu noktaya döndürülebilir.'),
  ('Modern işlemcilerdeki Intel VT-x ve AMD-V gibi özellikler neyi sağlar?', 'Sanallaştırmanın donanım desteğiyle hızlanmasını', ['İşlemcinin aşırı ısınmasının tamamen engellenmesini', 'Belleğin hata düzeltme kodu kullanmasını', 'Ekran kartının kablosuz bağlanmasını'], 'Bu uzantılar, konuk işletim sisteminin ayrıcalıklı komutlarını donanım düzeyinde yakalayarak sanal makinelerin neredeyse yerel hızda çalışmasını sağlar.'),
  ('RAID 0 dizisindeki disklerden biri bozulursa ne olur?', 'Dizideki tüm veriler kaybolur', ['Hiçbir veri kaybolmaz, dizi çalışmaya devam eder', 'Yalnızca bozulan diskteki yarım dosyalar etkilenir, kalanı tam kalır', 'Dizi kendiliğinden RAID 1\'e dönüşür'], 'RAID 0 verileri şeritler hâlinde disklere böler ve yedeklilik içermez; bir disk giderse dosyaların parçaları eksik kalır.'),
  ('2 TB\'lık dört diskten oluşan bir RAID 5 dizisinin kullanılabilir kapasitesi ne kadardır?', '6 TB', ['8 TB', '4 TB', '2 TB'], 'RAID 5\'te bir diskin kapasitesi eşlik (parity) bilgisine ayrılır: (4 − 1) × 2 TB = 6 TB.'),
  ('Bir veri merkezinde 1 TB\'lık dört sürücü, yansıtılmış çiftlerin şeritlenmesiyle (RAID 10) birleştiriliyor. Bu birime toplam en çok ne kadar veri yazılabilir?', '2 TB', ['4 TB', '3 TB', '1 TB'], 'RAID 10 diskleri yansıtılmış çiftlere ayırıp bu çiftleri şeritler; kapasitenin yarısı yansıtmaya gider: 4 × 1 TB / 2 = 2 TB.'),
  ('Mikrodenetleyiciyi (ör. Arduino kartlarındaki) sıradan bir mikroişlemciden ayıran özellik nedir?', 'İşlemci, bellek ve G/Ç birimlerini tek yongada toplaması', ['Her zaman bir masaüstü işletim sistemi çalıştırması gerekmesi', 'Yalnızca ekran kartı olarak kullanılabilmesi', 'Hiç belleğe sahip olmaması'], 'Mikrodenetleyici çekirdek, flash, RAM, zamanlayıcılar ve giriş-çıkış pinlerini bir yongada barındırır; ek bileşen gerektirmeden cihaz denetleyebilir.'),
  ('Bir mikrodenetleyicinin analog sıcaklık sensöründen gelen gerilimi sayıya çevirmesini sağlayan birim hangisidir?', 'ADC (analog-sayısal dönüştürücü)', ['DAC (sayısal-analog dönüştürücü)', 'ALU (aritmetik mantık birimi)', 'MMU (bellek yönetim birimi ve TLB)'], 'ADC sürekli değişen gerilimi örnekleyip ikilik sayıya çevirir; DAC bunun tersini yapar.'),
  ('10 bitlik bir ADC, 0–5 V aralığını kaç farklı sayısal düzeye böler?', '1024', ['1000', '512', '2048'], '10 bit ile 2¹⁰ = 1024 düzey elde edilir (0\'dan 1023\'e); her adım yaklaşık 5 / 1024 ≈ 4,9 mV\'a karşılık gelir.'),
  ('Pil ile yıllarca çalışması gereken bir hava istasyonu sensörü tasarlanıyor. Hangi yaklaşım pil ömrünü en çok uzatır?', 'Ölçüm aralarında denetleyiciyi derin uykuya almak', ['Sürekli en yüksek saat hızında çalıştırmak', 'Daha büyük bir renkli ekran eklemek', 'Mikrodenetleyici yerine masaüstü işlemci kullanmak'], 'Derin uykuda akım mikroamper düzeyine iner; cihaz yalnızca ölçüm zamanı geldiğinde uyanıp kısa sürede yeniden uyur.'),
  ('İki işlemciden birinin saat hızı daha yüksek olsa da diğerinin daha hızlı çalışabilmesini en iyi açıklayan kavram hangisidir?', 'Çevrim başına komut sayısı', ['Kasanın boyutu ve rengi', 'Güç kaynağının kablo uzunluğu ve rengi', 'Monitörün en-boy oranı'], 'Başarım = saat hızı × IPC\'dir; mimarisi daha verimli olan işlemci her çevrimde daha çok iş yaparak düşük frekansta bile önde olabilir.'),
  ('2 GHz\'lik bir işlemcide ortalama CPI (komut başına çevrim) 2 ise, 10⁹ komutluk bir program kaç saniyede çalışır?', '1 saniye', ['0,5 saniye', '2 saniye', '4 saniye'], 'Süre = komut sayısı × CPI / saat hızı = 10⁹ × 2 / (2 × 10⁹) = 1 saniye.'),
  ('Benchmark (başarım sınama) yazılımlarının donanım karşılaştırmalarında kullanılmasının amacı nedir?', 'Sistemleri aynı iş yüküyle ölçüp karşılaştırmak', ['Bilgisayardaki zararlı yazılımları bulup temizlemek', 'İşletim sistemini yeniden kurmak', 'Disk bölümlerini birleştirmek'], 'Standart bir iş yükü bütün sistemlerde aynı biçimde çalıştırıldığında sonuçlar yan yana konarak nesnel bir karşılaştırma yapılabilir.'),
  ('Bir oyun sırasında işlemci kullanımı %30\'da kalırken GPU kullanımı sürekli %100\'de seyrediyor. Kare hızını sınırlayan bileşen hangisidir?', 'Ekran kartı', ['İşlemci', 'Güç kaynağının kablosu', 'Klavye denetleyicisi'], 'Tam yükte çalışan bileşen darboğazdır; işlemci boş kapasite taşırken GPU kare üretimine yetişemiyor.'),
  ('"Gecikme" (latency) ile "bant genişliği" (bandwidth) arasındaki fark hangisinde doğru verilmiştir?', 'Gecikme ilk verinin gelme süresi, bant genişliği aktarım hızıdır', ['Gecikme ile bant genişliği her zaman birbirine eşit olan iki ayrı birimdir', 'Bant genişliği yalnızca ekran kartlarında ölçülen bir değerdir', 'Gecikme yalnızca saniyedeki bayt sayısıyla ölçülür'], 'Bir bellek düşük gecikmeli ama dar bant genişlikli ya da tersi olabilir; ikisi başarımın farklı yönlerini ölçer.'),
  ('Kapasitesi 4000 mAh ve anma gerilimi 3,85 V olan bir telefon pili yaklaşık kaç watt-saat enerji depolar?', '15,4 Wh', ['4,0 Wh', '1,54 Wh', '154 Wh'], 'Enerji = kapasite × gerilim = 4 Ah × 3,85 V = 15,4 Wh.'),
  ('60 Wh\'lik pile sahip bir dizüstü bilgisayar ortalama 15 W güç harcıyorsa pil yaklaşık kaç saat dayanır?', '4 saat', ['9 saat', '2 saat', '6 saat'], 'Süre = enerji / güç = 60 Wh / 15 W = 4 saat (kayıplar ihmal edilmiştir).'),
  ('Lityum-iyon pillerin kapasitesinin yıllar içinde azalmasının başlıca nedeni hangisidir?', 'Çevrimlerle elektrotların kimyasal olarak yıpranması', ['Pildeki lityumun buharlaşarak kasadan dışarı sızması', 'Ekranın pilin içindeki gerilimi düşürmesi', 'Pilin manyetik alanının zayıflaması'], 'Her çevrimde elektrot yüzeyinde istenmeyen katmanlar oluşur ve aktif malzeme azalır; yüksek sıcaklık bu yaşlanmayı hızlandırır.'),
  ('Lityum-iyon pilli bir telefonun ömrünü uzatmak için aşağıdaki alışkanlıklardan hangisi en uygundur?', 'Aşırı sıcaktan ve uzun süre %0\'da kalmaktan korumak', ['Pili her gün tamamen bitirip sonra %100\'e doldurmak', 'Telefonu şarj olurken güneş altında bırakmak', 'Pili ayda bir dondurucuda soğutmak'], 'Lityum-iyon piller ısıdan ve derin deşarjdan zarar görür; eski nikel pillerdeki "hafıza etkisi" bunlarda yoktur, bu yüzden tam boşaltmaya gerek yoktur.'),
  ('Akıllı telefonlarda işlemci, GPU, modem ve diğer birimlerin tek yongada toplandığı tasarıma ne ad verilir?', 'Yonga üstü sistem', ['Çok yongalı modül anakartı', 'RAID denetleyicisi', 'Genişletilmiş bölüm'], 'SoC (System on a Chip) yer, maliyet ve enerji tasarrufu sağlar; bu yüzden telefon ve tabletlerin temel yapı taşıdır.'),
  ('Telefon kameralarında görüntüyü elektrik sinyaline çeviren yarı iletken bileşen hangisidir?', 'Görüntü algılayıcısı', ['Ortam ışığı algılayıcısı', 'Lityum-iyon pil hücresi', 'Titreşim motoru ve bağlantı kablosu'], 'CMOS görüntü algılayıcısındaki milyonlarca ışığa duyarlı hücre, gelen ışığı elektrik yüküne çevirir; bu değerler sayısal görüntüye dönüştürülür.'),
  ('Windows\'taki "Sistem Geri Yükleme" özelliği ne işe yarar?', 'Sistem dosyalarını ve ayarlarını önceki bir noktaya döndürür', ['Silinmiş kişisel fotoğraf ve belgeleri her koşulda eksiksiz kurtarır', 'Bozuk bir sabit diski fiziksel olarak onarır', 'İşletim sistemini başka bir bilgisayara taşır'], 'Sistem Geri Yükleme kayıt defteri, sürücüler ve sistem dosyalarını önceki duruma getirir; kişisel dosyaları yedeklemez, bu yüzden yedeğin yerini tutmaz.'),
  ('Süper bilgisayarların başarımı genellikle hangi ölçütle ifade edilir?', 'FLOPS (kayan nokta işlemi/saniye)', ['RPM (dakikadaki devir sayısı)', 'DPI (inç başına basılan nokta sayısı)', 'PPI (inç başına piksel)'], 'Bilimsel hesaplar kayan noktalı sayılarla yapıldığından süper bilgisayarlar petaFLOPS, exaFLOPS gibi birimlerle sıralanır.'),
  ('Sunucuların kurumlarda genellikle 19 inçlik dolaplara takılan yassı kasalarda kullanılmasının başlıca nedeni nedir?', 'Sınırlı alana çok sayıda makineyi düzenli sığdırmak', ['Sunucuların masaüstü kasalara fiziksel olarak sığmaması', 'Dolapların işlemciyi kendiliğinden hızlandırması', 'Raf kasaların hiçbir soğutma gerektirmemesi'], 'Raf tipi kasalar "U" birimiyle ölçülür; veri merkezlerinde kablolama, soğutma ve bakımı kolaylaştırırken yoğun yerleşime olanak tanır.'),
  ('Bankalar ve havayolları gibi kurumların çok yüksek hacimli işlemleri işlemek için kullandığı, son derece güvenilir büyük bilgisayar sınıfına ne denir?', 'Ana bilgisayar', ['Tek kartlı eğitim bilgisayarı', 'Mikrodenetleyici', 'Netbook'], 'Ana bilgisayarlar saniyede binlerce işlemi yüksek güvenilirlikle işler; sıcak değiştirilebilir bileşenler sayesinde neredeyse hiç durmadan çalışır.'),
  ('Kendi işlem gücü çok düşük olan ve uygulamaları uzaktaki bir sunucuda çalıştırıp yalnızca ekran görüntüsünü gösteren bilgisayara ne ad verilir?', 'İnce istemci', ['İş istasyonu', 'Süper bilgisayar', 'Kalın sunucu'], 'İnce istemciler merkezi yönetim kolaylığı sağlar; işlem yükü sunucuda olduğu için az bakım gerektirir.'),
  ('Moore yasası olarak bilinen gözlem neyi öngörür?', 'Transistör sayısının yaklaşık iki yılda bir ikiye katlanmasını', ['İşlemci saat hızının her yıl tam olarak ve kesintisiz iki katına çıkmasını', 'Bilgisayar fiyatlarının her yıl yarıya düşmesini', 'Disk kapasitesinin her ay ikiye katlanmasını'], 'Gordon Moore\'un gözlemi bir doğa yasası değil, yarı iletken endüstrisinin onlarca yıl izlediği bir eğilimdir.'),
  ('Telefon işlemcilerindeki big.LITTLE gibi karma çekirdek tasarımlarının amacı nedir?', 'Hafif işleri az enerji harcayan çekirdeklere vermek', ['Bütün çekirdekleri her zaman en yüksek saat hızında ve aynı anda çalıştırmak', 'İşlemcinin önbelleğini tamamen kaldırmak', 'Telefonun yalnızca tek çekirdek kullanmasını sağlamak'], 'Güçlü çekirdekler yoğun işlerde, verimli çekirdekler arka plan işlerinde kullanılır; böylece hem başarım hem pil ömrü korunur.'),
  ('İşlemcilerdeki "turbo" ya da "boost" özelliği ne yapar?', 'Isı ve güç izin verdikçe saat hızını geçici olarak yükseltir', ['İşlemcinin çekirdek sayısını kalıcı olarak iki katına çıkarır', 'RAM\'i işlemcinin önbelleği gibi kullanır', 'İşlemciyi her zaman en düşük hızda tutar'], 'Turbo Boost gibi teknolojiler yük altında ve sıcaklık uygunken bazı çekirdekleri temel frekansın üzerine çıkarır.'),
  ('Yarı iletken üretiminde işlemci yongalarının kesildiği ince, yuvarlak silisyum diske ne ad verilir?', 'Yonga plakası (wafer)', ['Disk plakası (platter)', 'Soket (socket)', 'Isı dağıtıcı (heat spreader)'], 'Yüzlerce yonga aynı silisyum pul üzerinde fotolitografiyle üretilir, sonra kesilip paketlenir.'),
  ('RAM modüllerinde belirtilen "CL16" gibi CAS gecikmesi değeri neyi gösterir?', 'Okuma komutu ile verinin gelişi arasındaki çevrim sayısını', ['Modüldeki toplam yonga sayısını', 'Belleğin kaç yıl dayanacağını', 'Modülün güvenle çalışabildiği en yüksek ortam sıcaklığı değerini'], 'CAS gecikmesi, sütun adresi verildikten sonra verinin hazır olması için gereken bellek saati çevrimi sayısıdır; düşük değer daha hızlı yanıt demektir.'),
  ('DDR4 bellek modülünün DDR5 destekleyen bir anakart yuvasına takılamamasının nedeni nedir?', 'Çentik konumlarının ve elektriksel yapılarının farklı olması', ['DDR5 yuvalarının yalnızca dizüstü bilgisayarlarda bulunabilmesi', 'DDR4 modüllerinin her zaman daha büyük kapasiteli olması', 'İki türün aynı gerilimde çalışıp birbirini bozması'], 'Her DDR nesli farklı gerilim, sinyal ve pin düzenine sahiptir; yanlış takılmayı önlemek için çentikler farklı yerlere konmuştur.'),
  ('Anakart ayarlarında etkinleştirilen XMP (ya da EXPO) profilleri ne işe yarar?', 'Belleği üreticinin sınadığı hız ve zamanlamalarla çalıştırmak', ['Belleğin içeriğini elektrik kesilince korumak', 'Bellek modüllerinin rengini ve RGB aydınlatmasını kalıcı olarak değiştirmek', 'İşletim sistemini bellekten başlatmak'], 'Bellek varsayılan olarak standart (JEDEC) hızda açılır; XMP, modülün desteklediği daha yüksek frekans ve zamanlama değerlerini otomatik uygular.'),
  ('SATA III arayüzünün kuramsal en yüksek veri aktarım hızı ne kadardır?', '6 Gbit/s', ['1,5 Gbit/s', '3 Gbit/s', '32 Gbit/s'], 'SATA I 1,5, SATA II 3, SATA III ise 6 Gbit/s hızındadır; kodlama yükü nedeniyle pratik sınır yaklaşık 600 MB/s\'dir.'),
  ('Depolama aygıtlarının saniyede yapabildiği okuma-yazma işlemi sayısını belirten ölçüte ne ad verilir?', 'IOPS', ['RPM', 'FPS', 'DPI'], 'IOPS (saniyedeki G/Ç işlemi), özellikle küçük rastgele erişimlerde başarımı gösterir; SSD\'ler bu ölçütte HDD\'leri çok geride bırakır.'),
  ('SSD\'lerin üretici belgelerinde belirtilen TBW değeri neyi ifade eder?', 'Ömür boyunca yazılabilecek toplam veri miktarını', ['Diskin bir saniyede okuyabildiği terabayt miktarını', 'Diskin içindeki flash yonga sayısını', 'Diskin en yüksek çalışma sıcaklığını'], 'TBW (terabytes written), hücrelerin yıpranmasına göre belirlenen dayanıklılık değeridir; ör. 600 TBW, ömür boyunca yaklaşık 600 TB yazma demektir.'),
  ('Güçlü masaüstü ekran kartlarının anakart yuvasının yanı sıra güç kaynağından ek kabloyla beslenmesinin nedeni nedir?', 'Yuvanın verebildiği gücün kartın gereksinimine yetmemesi', ['Kartın görüntü sinyalini monitöre güç kablosu üzerinden göndermesi', 'Ek kablonun kartı soğutmaya yaraması', 'Kartın sürücüsünü güç kaynağından okuması'], 'PCIe ×16 yuvası en çok 75 W sağlar; daha fazla güç çeken kartlar 6 ya da 8 pinli (veya daha yeni) PCIe güç bağlantılarıyla beslenir.'),
  ('Gerçek zamanlı ışın izleme (ray tracing) özelliğinin oyunlarda sağladığı temel görsel iyileşme nedir?', 'Işık, yansıma ve gölgelerin daha gerçekçi hesaplanması', ['Ekran çözünürlüğünün kendiliğinden ve kalıcı olarak iki katına çıkması', 'Kare hızının her zaman artması', 'Oyunun daha az bellek kullanması'], 'Işın izleme, ışık ışınlarının sahnedeki nesnelerle etkileşimini benzeterek gerçekçi yansıma, kırılma ve gölge üretir; ancak yoğun hesap gerektirir.'),
  ('Ekranlarda her pikselin genellikle kırmızı, yeşil ve mavi alt piksellerden oluşmasının nedeni nedir?', 'Üç ana rengin ışık olarak karışıp çok sayıda renk vermesi', ['Üç rengin ekranın elektrik tüketimini sıfırlaması', 'Mavi ışığın tek başına beyazı oluşturabilmesi', 'Göz yalnızca bu üç rengi görebildiği için öteki renklerin var olmaması'], 'Eklemeli renk karışımında kırmızı, yeşil ve mavinin farklı yoğunlukları birleşerek göze milyonlarca farklı renk olarak görünür.'),
  ('OLED ekranlarda uzun süre aynı sabit görüntünün gösterilmesiyle oluşabilen kalıcı iz sorununa ne ad verilir?', 'Yanma (burn-in)', ['Yırtılma (tearing)', 'Titreme (flicker)', 'Arka ışık sızması (bleeding)'], 'Organik malzemeler kullanıldıkça yaşlanır; hep aynı yerde aynı öğeyi gösteren pikseller ötekilerden farklı yıpranarak kalıcı iz bırakabilir.'),
  ('Ekran parlaklığını belirtmek için sık kullanılan "nit" birimi neye eşittir?', 'Bir kandela/metrekare', ['Saniyede bir kare', 'İnç başına bir piksel', 'Watt başına bir lümen ışık akısı'], '1 nit = 1 cd/m²; HDR ekranlar yüksek parlaklık değerleriyle daha geniş bir parlaklık aralığı gösterebilir.'),
  ('Eski CRT monitörlerde görüntü nasıl oluşturuluyordu?', 'Elektron ışınının fosfor kaplı ekranı taramasıyla', ['Sıvı kristallerin arka ışığı süzmesiyle', 'Her pikselin organik bir diyotla kendi ışığını yaymasıyla', 'Lazer ışığının duvara yansıtılmasıyla'], 'Katot ışın tüpündeki elektron tabancası mıknatıslarla yönlendirilir; çarptığı fosfor noktaları ışık yayar.'),
  ('Bir klavyede "N-key rollover" özelliğinin bulunması ne anlama gelir?', 'Aynı anda basılan bütün tuşların algılanması', ['Klavyenin N harfini iki kez yazması', 'Tuşların ışıklarının sırayla yanıp sönmesi', 'Klavyenin yalnızca rakam tuşlarını tanıyabilmesi'], 'Ucuz klavyeler matris yapısı nedeniyle birkaç tuştan sonrasını kaçırabilir (ghosting); NKRO destekli klavyelerde her tuş bağımsız algılanır.'),
  ('Eski ATM\'lerde ve bazı endüstriyel panellerde kullanılan, ekrana uygulanan basınçla çalışan dokunmatik teknolojisi hangisidir?', 'Dirençli (rezistif) dokunmatik', ['Kapasitif dokunmatik', 'Kızılötesi yakınlık algılayıcısı tabanlı ekran', 'Optik fare algılayıcısı'], 'Dirençli ekranda basınç iki iletken katmanı birbirine değdirir; eldivenle ya da kalemle de çalışır ama çoklu dokunmayı genellikle desteklemez.'),
  ('Linux\'ta adı nokta (.) ile başlayan dosyalar, örneğin ".bashrc", için hangisi doğrudur?', 'Varsayılan listelemede gizli kalırlar', ['Yalnızca yönetici tarafından okunabilen ve hiçbir kullanıcının açamadığı dosyalardır', 'Çalıştırılabilir program dosyalarıdır', 'Silinemeyen sistem dosyalarıdır'], 'Unix geleneğinde nokta ile başlayan adlar gizli sayılır; "ls -a" komutu bunları da listeler. Genellikle kullanıcı ayar dosyaları böyle adlandırılır.'),
  ('Linux\'ta "/home/ayse/belgeler/odev.txt" ile "belgeler/odev.txt" yolları arasındaki fark nedir?', 'İlki mutlak, ikincisi bulunulan dizine göre göreli yoldur', ['İlki göreli yoldur, ikincisi ise kök dizinden başlayan mutlak yoldur', 'İkisi her durumda aynı dosyayı gösterir', 'İkinci yol yalnızca Windows\'ta geçerlidir'], '"/" ile başlayan yol kök dizinden başlar ve her yerden aynı dosyayı gösterir; göreli yol ise geçerli dizine göre çözülür.'),
  ('Linux dosya hiyerarşisinde sistem günlükleri gibi sürekli değişen veriler geleneksel olarak hangi dizinde tutulur?', '/var', ['/usr', '/bin', '/opt'], '/var (variable) günlükler (/var/log), kuyruklar ve önbellekler gibi değişken verileri barındırır.'),
  ('Linux\'ta arka planda sürekli çalışan ve kullanıcıyla doğrudan etkileşmeyen hizmet süreçlerine ne ad verilir?', 'Daemon (artalan hizmeti)', ['Zombi süreç', 'Kabuk betiği (shell script)', 'Çekirdek modülü'], 'Daemon\'lar (ör. sshd, cron) genellikle açılışta başlatılır ve arka planda istekleri bekler; Windows\'ta karşılıkları "hizmet" (service) olarak adlandırılır.'),
  ('Linux\'ta her gün saat 02.00\'de bir yedekleme betiğini otomatik çalıştırmak için en uygun araç hangisidir?', 'cron', ['grep', 'chmod', 'fdisk'], 'cron, crontab dosyasındaki zamanlamalara göre komutları belirli dakika, saat, gün ya da haftalarda otomatik çalıştırır.'),
  ('Linux çekirdeği kurtarılamaz bir hatayla karşılaşıp sistemi durdurduğunda bu duruma ne ad verilir?', 'Çekirdek paniği (kernel panic)', ['Sayfa hatası', 'Bağlam değişimi', 'Kesme isteği (IRQ)'], 'Çekirdek paniği, Windows\'taki mavi ekran hatasının (BSOD) Linux ve macOS\'taki karşılığıdır; sistem veri bozulmasını önlemek için durur.'),
  ('64 bit Windows\'ta "Program Files (x86)" adlı ikinci bir program klasörünün bulunmasının nedeni nedir?', '32 bitlik programların ayrı tutulması', ['Bozuk programların karantinaya alınması', 'Yalnızca Microsoft uygulamalarının saklanması', 'Programların yedek kopyalarının otomatik olarak saklanması'], '64 bit Windows WOW64 katmanıyla 32 bit uygulamaları çalıştırır; bunların dosyaları ve kitaplıkları karışmasın diye ayrı klasörde tutulur.'),
  ('Windows\'ta bir dosyanın uzantısı ".txt"den ".exe"ye değiştirilirse ne olur?', 'İçerik aynı kalır, yalnızca dosya türü yanlış tanınır', ['Dosya kendiliğinden çalışan bir programa dönüştürülür', 'Dosyanın içeriği tamamen silinir', 'Dosya şifrelenir'], 'Uzantı yalnızca işletim sisteminin dosyayı hangi programla açacağını belirleyen bir etikettir; içeriği dönüştürmez.'),
  ('Windows Komut İstemi\'nde bir diskin dosya sistemi hatalarını tarayıp düzelten komut hangisidir?', 'chkdsk', ['tasklist', 'format', 'diskpart'], 'chkdsk (check disk) dosya sistemi tutarlılığını denetler, /f seçeneğiyle hataları düzeltir; format ise diski biçimlendirir ve verileri siler.'),
  ('Windows\'ta Ctrl + Alt + Del tuş birleşiminin güvenlik açısından önemi nedir?', 'Sahte giriş ekranlarınca yakalanamaması', ['Bilgisayarı anında ve kayıtsız biçimde kapatması', 'Tüm parolaları sıfırlaması', 'Ekran görüntüsünü kaydetmesi'], 'Bu "güvenli dikkat dizisi" doğrudan işletim sistemi tarafından işlenir; sıradan uygulamalar onu engelleyemez, bu yüzden açılan ekranın gerçek Windows ekranı olduğu bilinir.'),
  ('Bir ofiste birden çok kişinin aynı anda yazıcıya belge göndermesinde, belgelerin sırayla basılmasını sağlayan işletim sistemi mekanizması hangisidir?', 'Yazdırma kuyruğu', ['Disk birleştirme ve sıkıştırma işlemi', 'Bağlam değiştirme', 'Sayfa değişimi'], 'Spooler belgeleri önce diske alıp sıraya koyar; yazıcı hazır oldukça işleri tek tek gönderir, böylece uygulamalar beklemek zorunda kalmaz.'),
  ('İşletim sisteminin dosya sistemi yönetimi kapsamındaki görevlerden biri hangisidir?', 'Dosyaların yerini ve erişim izinlerini izlemek', ['İşlemcinin saat hızını belirleyip fabrikada sabitlemek', 'Monitörün panel türünü değiştirmek', 'Klavyedeki harflerin yerini değiştirmek'], 'Dosya sistemi katmanı dosya adlarını, dizinleri, blok ayırmayı ve izinleri yönetir; uygulamalar yalnızca "dosya aç, oku, yaz" der.'),
  ('Grafik kullanıcı arayüzü (GUI) ile komut satırı arayüzü (CLI) karşılaştırıldığında CLI\'nin üstünlüklerinden biri hangisidir?', 'İşlerin betiklerle kolayca otomatikleştirilmesi', ['Yeni başlayanlar için her zaman daha kolay ve anlaşılır olması', 'Fare kullanımını zorunlu kılması', 'Görsellerin daha iyi görüntülenmesi'], 'Komutlar betik dosyalarına yazılıp tekrar tekrar çalıştırılabilir; yüzlerce dosyada aynı işi yapmak CLI ile çok hızlıdır.'),
  ('Kalan süresi en kısa olan önce (SRTF) algoritması SJF\'den hangi yönüyle ayrılır?', 'Daha kısa iş gelince çalışanı kesebilir', ['Süreçleri her zaman geliş sırasına göre ve kesmeden çalıştırır', 'Süreçlere eşit zaman dilimleri verir', 'Önceliği kullanıcı belirler'], 'SRTF, SJF\'nin kesintili sürümüdür; yeni gelen sürecin toplam isteği, çalışanın kalan süresinden kısaysa işlemci yeni sürece geçer.'),
  ('Etkileşimli masaüstü sistemlerinde zamanlayıcıların klavye ve fare olaylarını bekleyen süreçlere öncelik tanımasının amacı nedir?', 'Kullanıcıya hızlı tepki vermek', ['Toplam disk kullanımını artırmak', 'İşlemcinin çekirdek sayısını düşürmek', 'Uzun hesaplama işlerinin tamamen durdurulmasını sağlamak'], 'G/Ç ağırlıklı etkileşimli süreçler kısa işlemci patlamaları kullanır; onlara öncelik vermek, sistemin kullanıcıya akıcı görünmesini sağlar.'),
  ('Zamanlama ölçütlerinden "verim" (throughput) neyi ifade eder?', 'Birim zamanda tamamlanan süreç sayısını', ['Bir sürecin ilk yanıtına kadar geçen süreyi', 'Süreçlerin hazır kuyruğunda bekledikleri toplam süreyi', 'İşlemcinin sıcaklığını'], 'Verim, örneğin saniyede biten iş sayısıdır; sistemin ne kadar iş çıkardığının ölçüsüdür.'),
  ('Birden çok iş parçacığının paylaşılan veriye eriştiği ve aynı anda yalnız birinin bulunması gereken kod parçasına ne ad verilir?', 'Kritik bölge', ['Önyükleme sektörü', 'Kesme vektörü', 'Sayfa tablosu girişi'], 'Kritik bölgeye giriş muteks ya da semafor gibi araçlarla denetlenir; böylece yarış durumları önlenir.'),
  ('Bir kilidi beklerken uyumak yerine döngü içinde sürekli kilidin açılıp açılmadığını sınayan kilit türü hangisidir?', 'Döner kilit', ['Sayaçlı semafor', 'Okuma-yazma dosya kilidi', 'Koşul değişkeni'], 'Spinlock beklerken işlemciyi meşgul eder; bu yüzden yalnızca kilidin çok kısa süre tutulacağı, çok çekirdekli durumlarda verimlidir.'),
  ('Bir programda çağrılan fonksiyonların yerel değişkenlerinin ve dönüş adreslerinin tutulduğu bellek bölgesine ne ad verilir?', 'Yığın (stack)', ['Öbek (heap)', 'Kod bölümü', 'Önbellek satırı'], 'Her fonksiyon çağrısı yığına bir çerçeve ekler, dönüşte bu çerçeve kaldırılır; dinamik ayrılan bellek ise öbekte (heap) yer alır.'),
  ('Bir sürecin sayfalarının ancak ilk kez erişildiklerinde diskten belleğe yüklenmesi yaklaşımına ne ad verilir?', 'İsteğe bağlı sayfalama', ['Ön belleğe alma', 'Bellek eşlemeli G/Ç', 'Sabit bölümlendirme'], 'Demand paging ile program başlarken tüm kodun yüklenmesine gerek kalmaz; kullanılmayan bölümler hiç RAM\'e gelmeyebilir.'),
  ('Linux\'ta "takas alanı" (swap) ne amaçla kullanılır?', 'RAM dolunca az kullanılan sayfaları diske almak', ['İşlemcinin önbelleğini genişletmek', 'Silinen dosyaları geri dönüşüm için geçici olarak tutmak', 'Ekran kartının belleğini artırmak'], 'Takas alanı ayrı bir bölüm ya da dosya olabilir; RAM yetmediğinde etkin olmayan sayfalar buraya yazılır, ama disk RAM\'den çok yavaştır.'),
  ('Küme (cluster) boyutu 4 KB olan bir dosya sisteminde 10 KB\'lık bir dosya diskte kaç KB yer kaplar?', '12 KB', ['10 KB', '8 KB', '16 KB'], 'Dosya 3 küme gerektirir (4 + 4 + 2); son kümenin kullanılmayan 2 KB\'ı da ayrıldığından diskte 12 KB yer tutar.'),
  ('NTFS\'in desteklediği, bir klasördeki dosyaları kullanıcı fark etmeden diskte daha az yer kaplayacak biçimde saklayan özellik hangisidir?', 'Dosya sıkıştırma', ['Disk birleştirme', 'Sanal bellek', 'Hızlı başlatma'], 'NTFS sıkıştırması dosyaları saydam biçimde sıkıştırır; dosya okunurken açılır, uygulamalar farkı görmez.'),
  ('Linux\'ta diskler ve bölümler genellikle "/dev/sda1" gibi adlarla görünür. Bu addaki "1" neyi gösterir?', 'İlk diskin birinci bölümünü', ['Diskin kapasitesini terabayt cinsinden', 'Diskin dönüş hızını', 'Diske bağlı kullanıcı sayısını'], 'sda ilk SATA/SCSI diski, sonundaki sayı ise o diskteki bölüm numarasını gösterir; NVMe diskler /dev/nvme0n1p1 biçiminde adlandırılır.'),
  ('ATX standardındaki anakartları güç kaynağına bağlayan ana güç konnektörü kaç pinlidir?', '24', ['4', '12', '40'], 'Günümüz ATX anakartlarında 24 pinli ana güç konnektörü ve işlemci için ayrıca 4 ya da 8 pinli EPS konnektörü kullanılır.'),
  ('Bir bilgisayar açıldığında ekrana görüntü gelmiyor ve kasa hoparlöründen belirli bir düzende bip sesleri duyuluyor. Bu sesler neyi bildirir?', 'POST sırasında saptanan donanım hatasını', ['İşletim sisteminin başarıyla güncellendiğini', 'Klavyenin pilinin bittiğini', 'Ekranın parlaklığının çok düşük olduğunu'], 'Ekran çalışmadan önce oluşan hatalar bip kodlarıyla bildirilir; örneğin bellek ya da ekran kartı takılı değilse farklı bip dizileri duyulur.'),
  ('Anakart üzerindeki "CMOS temizleme" atlama teli (jumper) ya da düğmesi hangi durumda kullanılır?', 'Ürün yazılımı ayarlarını sıfırlamak için', ['Sabit diskteki tüm verileri kalıcı olarak silmek için', 'İşlemciyi hız aşırtmak için', 'İşletim sistemini yeniden kurmak için'], 'Hatalı bir hız aşırtma ya da unutulan BIOS parolası yüzünden açılmayan sistemlerde ayarlar sıfırlanarak sorun giderilebilir.'),
  ('Kasanın önünden soğuk havayı alan, arkasından ve üstünden sıcak havayı atan fan yerleşimi neden tercih edilir?', 'Sıcak hava doğal olarak yükseldiğinden akış düzenli olur', ['Fanların bu yönde daha az elektrik harcamak zorunda olması', 'Tozun kasaya hiç girememesi', 'Kasanın ağırlığının azalması'], 'Önden arkaya ve aşağıdan yukarıya hava akışı, ısınan havanın doğal yükselişiyle uyumludur ve bileşenlerden ısıyı verimli uzaklaştırır.'),
  ('Modüler güç kaynaklarının modüler olmayanlara göre başlıca kolaylığı nedir?', 'Yalnız gerekli kabloların takılabilmesi', ['Daha yüksek verim sertifikasını zorunlu olarak alabilmeleri', 'Hiç fan gerektirmemeleri', 'Alternatif akımla bileşenleri doğrudan beslemeleri'], 'Kullanılmayan kablolar takılmadığı için kasa içi düzenli kalır ve hava akışı iyileşir.'),
  ('Intel ve Apple\'ın birlikte geliştirdiği, Type-C bağlayıcı üzerinden yüksek hızlı veri, görüntü ve güç taşıyabilen arayüz hangisidir?', 'Thunderbolt', ['FireWire 400', 'PS/2', 'Seri port'], 'Thunderbolt 3 ve sonrası Type-C bağlayıcı kullanır; PCIe ve DisplayPort sinyallerini tek kabloda taşıyarak harici ekran kartı ya da hızlı disk bağlanmasına olanak tanır.'),
  ('USB Power Delivery (USB PD) standardının sağladığı olanak hangisidir?', 'Cihazla anlaşıp daha yüksek güçle şarj etmek', ['Verileri kablosuz olarak aktarmak', 'USB kablosunu şifrelemek', 'Telefonun ekranını kablosuz olarak televizyona yansıtmak'], 'USB PD, şarj cihazı ile cihazın gerilim ve akım düzeyini görüşmesini sağlar; böylece dizüstü bilgisayarlar bile Type-C ile şarj edilebilir.'),
  ('Bilgisayara takılan bir ses kartının ya da mikrofonun belirtimlerindeki "48 kHz" değeri neyi ifade eder?', 'Sesin saniyede kaç kez örneklendiğini', ['Mikrofonun ses yüksekliği sınırını desibel olarak', 'Ses dosyasının kaç megabayt tutacağını', 'Kablonun uzunluğunu'], 'Örnekleme hızı, analog sesin saniyede kaç kez ölçülüp sayıya çevrildiğini gösterir; 48 kHz saniyede 48.000 örnek demektir.'),
  ('Bilgisayar belleğinde tek bir biti saklayabilen temel ardışık mantık devresine ne ad verilir?', 'Flip-flop', ['Çoklayıcı', 'Kod çözücü', 'Yarım toplayıcı'], 'Flip-flop, geri beslemeli kapılarla kurulur ve bir saat sinyaline göre durumunu değiştirene kadar 0 ya da 1 değerini korur; yazmaçlar ve SRAM bu yapıya dayanır.'),
  ('Bir girişi 1 olan VEYA (OR) kapısının çıkışı bir DEĞİL (NOT) kapısının girişine bağlanırsa NOT kapısının çıkışı ne olur?', '0', ['1', 'Girişe göre değişir', 'Tanımsız'], 'VEYA kapısının girişlerinden biri 1 ise çıkış 1\'dir; NOT kapısı bunu tersine çevirir ve sonuç 0 olur.'),
  ('IEEE 754 tek duyarlıklı kayan noktalı sayı biçimi toplam kaç bit kullanır?', '32', ['16', '64', '80'], 'Tek duyarlık 32 bittir (1 işaret, 8 üs, 23 kesir); çift duyarlık ise 64 bit kullanır.'),
  ('Linux\'ta "rm *.log" komutundaki yıldız (*) karakteri ne işe yarar?', 'Adı .log ile biten tüm dosyaları eşler', ['Yalnızca adı tam olarak "*.log" olan tek bir dosyayı seçer', 'Gizli dosyaları korumaya alır', 'Silinen dosyaları geri dönüşüm kutusuna gönderir'], 'Kabuk, * joker karakterini herhangi bir karakter dizisiyle eşleştirir; komut çalışmadan önce uygun dosya adları yerine yazılır.'),
  ('Linux\'ta büyük bir günlük dosyasının yalnızca son 10 satırını görmek için hangi komut kullanılır?', 'tail', ['head', 'less', 'wc'], 'tail varsayılan olarak son 10 satırı, head ilk 10 satırı gösterir; "tail -f" dosyaya eklenen yeni satırları canlı izler.'),
  ('Linux\'ta disk bölümlerinin toplam ve boş alanlarını insanların okuyabileceği biçimde (GB, MB) görmek için hangi komut kullanılır?', 'df -h', ['du -s', 'ls -l', 'free -m'], 'df (disk free) bağlı dosya sistemlerinin kullanımını gösterir; -h seçeneği boyutları okunaklı birimlerle yazar. du ise dizinlerin kapladığı alanı hesaplar.'),
  ('Linux\'ta yeni indirilen bir "kur.sh" betiğini çalıştırılabilir yapmak için hangi komut kullanılır?', 'chmod +x kur.sh', ['chown +x kur.sh', 'mkdir kur.sh', 'touch +x kur.sh'], 'chmod +x dosyaya çalıştırma izni ekler; ardından betik "./kur.sh" ile başlatılabilir.'),
  ('Linux\'ta bir dizinde ve alt dizinlerinde adı "rapor" ile başlayan dosyaları aramak için hangisi uygundur?', 'find . -name "rapor*"', ['grep . -name "rapor*"', 'ls -find rapor', 'cd rapor*'], 'find belirtilen dizinden başlayarak alt dizinlerde ölçütlere uyan dosyaları arar; grep ise dosya içeriklerinde metin arar.'),
  ('Linux\'ta "grep hata sistem.log" komutu ne yapar?', 'sistem.log içinde "hata" geçen satırları listeler', ['sistem.log dosyasını hata adlı yeni bir dosyaya kopyalar', '"hata" adlı dosyayı siler', 'sistem.log dosyasını sıkıştırır'], 'grep bir metin desenini dosya içinde arar ve eşleşen satırları ekrana yazar.'),
  ('Linux\'ta "proje" adlı dizini tüm içeriğiyle birlikte tek bir sıkıştırılmış arşiv dosyasına dönüştürmek için hangisi kullanılır?', 'tar -czf proje.tar.gz proje', ['mkdir -p proje.tar.gz', 'cp -r proje.tar.gz proje', 'ls -R proje > proje.gz'], 'tar dosyaları tek arşivde toplar; -c oluşturma, -z gzip sıkıştırması, -f arşiv adı belirtme seçenekleridir.'),
  ('Windows Komut İstemi\'nde çalışan süreçlerin listesini görmek için hangi komut kullanılır?', 'tasklist', ['systeminfo', 'cls', 'type'], 'tasklist süreçleri ve bellek kullanımlarını listeler; taskkill ile bir süreç sonlandırılabilir. cls ekranı temizler.'),
  ('Linux\'ta bir komutun çıktısını var olan bir dosyanın sonuna, eski içeriği silmeden eklemek için hangi işleç kullanılır?', '>>', ['>', '|', '<'], '">>" dosyaya ekleme yapar; ">" dosyayı baştan yazar, "<" bir dosyayı komuta girdi olarak verir, "|" ise iki komutu birbirine bağlar.'),
  ('macOS\'ta çalışan bir uygulamayı zorla kapatma penceresini açan klavye kısayolu hangisidir?', 'Command + Option + Esc', ['Command + Q', 'Control + Option + Delete', 'Command + Shift + 3'], 'Command + Option + Esc "Uygulamadan Çıkmaya Zorla" penceresini açar; Command + Q normal çıkış yapar, Command + Shift + 3 ekran görüntüsü alır.'),
  ('macOS\'un yalnızca Apple\'ın onayladığı ya da kimliği belirli geliştiricilerin imzaladığı uygulamaların açılmasına izin veren özelliği hangisidir?', 'Gatekeeper', ['Time Machine', 'Spotlight', 'Rosetta'], 'Gatekeeper indirilen uygulamaların imzasını ve noterlik onayını denetler; imzasız uygulamalar için kullanıcıyı uyarır.'),
  ('macOS\'taki "Disk İzlencesi" uygulamasıyla aşağıdakilerden hangisi yapılabilir?', 'Diskleri bölümlendirip biçimlendirmek', ['Uygulamaların işlemci kullanımını izleyip sınırlamak', 'Fotoğraf düzenlemek', 'Parolaları saklamak'], 'Disk İzlencesi (Disk Utility) disk silme, bölümleme, APFS birimleri oluşturma ve İlk Yardım ile dosya sistemi onarma işlevlerini sunar.'),
  ('Intel işlemcili Mac\'lerde ikinci bir bölüme Windows kurup açılışta iki sistem arasında seçim yapmayı sağlayan Apple aracı hangisidir?', 'Boot Camp', ['Gatekeeper', 'AirDrop', 'Spotlight'], 'Boot Camp Yardımcısı diski bölümlendirir ve Windows sürücülerini yükler; Apple Silicon Mac\'lerde bu araç bulunmaz.'),
  ('Android\'de uygulamaların bayt kodunu cihaza kurulurken önceden makine koduna derleyerek daha hızlı çalışmasını sağlayan çalışma zamanı hangisidir?', 'ART (Android Runtime)', ['JVM (Java Virtual Machine)', 'CLR (.NET ortak dil çalışma zamanı)', 'XNU çekirdeği'], 'ART, Android 5.0 ile Dalvik\'in yerini aldı; önceden derleme (AOT) sayesinde uygulama başlangıçları hızlandı ve pil tüketimi azaldı.'),
  ('Android\'de "kök erişimi elde etme" (rooting) işleminin kullanıcıya getirdiği temel değişiklik nedir?', 'Sistem dosyalarını değiştiren tam yönetici yetkisi', ['Telefonun işlemcisinin fiziksel olarak ve kalıcı biçimde hızlanması', 'Pil kapasitesinin artması', 'Ekranın çözünürlüğünün yükselmesi'], 'Rooting kullanıcıya Linux\'taki root yetkisini verir; sistem üzerinde tam denetim sağlar ama güvenlik korumalarını zayıflatır ve garantiyi etkileyebilir.'),
  ('Android\'de "Geliştirici seçenekleri" menüsü hangi yolla görünür hâle getirilir?', 'Telefon bilgilerindeki yapı numarasına art arda dokunarak', ['Telefonu kapatıp açarken ses açma tuşuna uzun süre basılı tutarak', 'Uygulama mağazasından ayrı bir uygulama indirerek', 'Şarj kablosunu üç kez takıp çıkararak'], 'Yapı numarasına yedi kez dokunulduğunda menü açılır; USB hata ayıklama ve animasyon hızı gibi ileri ayarlar buradadır.'),
  ('Windows\'ta Linux araçlarını ayrı bir sanal makine kurmadan çalıştırmaya olanak tanıyan özellik hangisidir?', 'WSL', ['Hyper-Threading çoklu iş parçacığı özelliği', 'BitLocker sürücü şifrelemesi', 'Windows Hello'], 'WSL, Windows içinde Linux dağıtımlarını çalıştırır; WSL 2 hafif bir sanal makine içinde gerçek Linux çekirdeği kullanır.'),
  ('Bir işlemcinin L3 önbelleğinin büyük olması hangi tür programlarda en belirgin yarar sağlar?', 'Büyük veri kümelerini sık kullanan programlarda', ['Yalnızca metin belgelerini yazdıran programlarda', 'Hiç bellek kullanmayan programlarda', 'Yalnızca klavye girdisi bekleyen programlarda'], 'Çalışma kümesi L3\'e sığan programlar RAM\'e daha seyrek gider; oyunlar, veri tabanları ve bilimsel hesaplar bundan yararlanır.'),
  ('Makine koduna bire bir karşılık gelen ve "MOV", "ADD" gibi kısaltmalarla yazılan düşük düzeyli programlama diline ne ad verilir?', 'Çevirme dili (assembly)', ['Biçimlendirme dili (HTML)', 'Sorgu dili (SQL)', 'Betik dili (Python)'], 'Assembly dilinde her komut bir makine komutuna karşılık gelir; çevirici (assembler) bunu ikilik koda dönüştürür ve dil işlemci mimarisine özgüdür.'),
  ('Eski BIOS sistemlerinde önyükleme kodunu ve bölüm tablosunu içeren, diskin ilk sektöründe bulunan kayıt kaç bayttır?', '512', ['1024', '256', '4096'], 'MBR diskin ilk 512 baytlık sektörüdür: 446 bayt önyükleme kodu, 64 bayt bölüm tablosu (4 × 16) ve 2 bayt imza (55AA) içerir.'),
  ('Bir veriyi kaynağından hedefe aktarılırken geçici olarak tutan bellek alanına ne ad verilir ve hangi sorunu hafifletir?', 'Tampon; hız farkını dengeler', ['Kayıt defteri; dosya adlarını saklar', 'Önyükleme sektörü; sistemi başlatır', 'Takas alanı; işlemciyi soğutur'], 'Örneğin video oynatılırken birkaç saniyelik veri tampona alınır; böylece üretici ile tüketici arasındaki anlık hız farkları kesintiye yol açmaz.'),
  ('Mürekkep püskürtmeli yazıcıların uzun süre kullanılmadığında baskı kalitesinin bozulmasının yaygın nedeni nedir?', 'Püskürtme uçlarında mürekkebin kuruması', ['Tamburun manyetik özelliğini yitirmesi', 'Tonerin ısıyla erimesi', 'Kâğıt tepsisinin kendiliğinden küçülmesi'], 'Mürekkep ince nozullarda kuruyup tıkanma yapabilir; yazıcıların kafa temizleme işlevi bu sorunu gidermeye yöneliktir.'),
  ('SD kartlarda "Class 10" ya da "U3" gibi işaretler neyi gösterir?', 'En düşük sürekli yazma hızını', ['Kartın toplam depolama kapasitesini', 'Kartın üretim yılını', 'Kartın dosya sistemini'], 'Class 10 en az 10 MB/s, U3 ise en az 30 MB/s sürekli yazma hızını garanti eder; yüksek çözünürlüklü video kaydı bu hızları gerektirir.'),
  ('128 GB\'lık bir bellek kartına, her biri ortalama 4 MB olan fotoğraflardan yaklaşık kaç tane sığar? (1 GB = 1000 MB alınız.)', '32.000', ['3.200', '512', '320.000'], '128 GB = 128.000 MB; 128.000 / 4 = 32.000 fotoğraf (dosya sistemi yükü ihmal edilmiştir).'),
  ('Yenileme hızı 120 Hz olan bir ekranda iki ardışık görüntü yenilemesi arasında yaklaşık kaç milisaniye geçer?', '8,3 ms', ['12 ms', '16,7 ms', '1,2 ms'], 'Süre = 1 / 120 s ≈ 0,00833 s = 8,3 ms; 60 Hz\'de bu süre 16,7 ms\'dir.'),
  ('RAM\'in erişim süresi yaklaşık 100 ns, bir NVMe SSD\'nin rastgele okuma gecikmesi yaklaşık 100 µs ise SSD bu örnekte kaç kat daha yavaştır?', '1000', ['100', '10', '10.000'], '100 µs = 100.000 ns; 100.000 / 100 = 1000 kat.'),
  ('Bilgisayar açıkken işletim sisteminin hangi bölümü sürekli RAM\'de kalır?', 'Çekirdek', ['Kurulum dosyaları', 'Yardım belgeleri', 'Duvar kâğıdı görselleri'], 'Çekirdek açılışta belleğe yüklenir ve bilgisayar kapanana kadar orada kalır; diğer bileşenler gerektiğinde yüklenir.'),
  ('Windows, macOS ve Linux\'un çekirdek yapıları hakkında hangisi doğrudur?', 'Linux monolitik, Windows ve macOS karma çekirdek kullanır', ['Üçü de saf mikroçekirdek kullanır', 'Windows yalnızca mikroçekirdekten oluşur, Linux\'un çekirdeği yoktur', 'macOS çekirdeği Linux\'un bir dağıtımıdır'], 'Windows NT çekirdeği ve macOS\'un XNU çekirdeği mikroçekirdek fikirlerini monolitik öğelerle birleştiren karma (hibrit) yapılardır.'),
  ('Bir web tarayıcısında her sekmenin ayrı bir süreç olarak çalıştırılmasının kullanıcıya yararı nedir?', 'Bir sekme çöküşünün ötekileri etkilememesi', ['Tüm sekmelerin toplamda daha az bellek kullanması', 'İnternet bağlantısının hızlanması', 'Sekmelerin otomatik olarak kapanması'], 'Süreçler bellek alanlarıyla birbirinden yalıtıldığı için tek bir sekmedeki hata tüm tarayıcıyı düşürmez; bunun bedeli daha fazla bellek kullanımıdır.'),
  ('Bir sürecin oluşturduğu iş parçacıklarının ayrı süreçlere göre daha hızlı oluşturulup aralarında geçiş yapılabilmesinin nedeni nedir?', 'Aynı adres alanını paylaşmaları', ['Her birinin ayrı bir sayfa tablosu gerektirmesi', 'Diskte ayrı dosyalar olarak saklanmaları', 'Her birinin ayrı bir işletim sistemi çalıştırması'], 'Yeni iş parçacığı için yeni adres alanı kurulmaz; geçişte sayfa tablosu değişmediğinden TLB de boşaltılmaz.'),
  ('Unix\'te sonlanmış ama ana süreci tarafından çıkış durumu henüz okunmamış sürece ne ad verilir?', 'Zombi süreç', ['Yetim süreç', 'Artalan süreci', 'Ön plan süreci'], 'Zombi süreç belleğini bırakmıştır ama süreç tablosunda girişi kalır; ana süreç wait() çağırınca tamamen silinir.'),
  ('Bir işletim sisteminin kilitlenmeyi fark ettikten sonra uygulayabileceği kurtarma yöntemlerinden biri hangisidir?', 'Döngüdeki süreçlerden birini sonlandırmak', ['Bilgisayarın ekran çözünürlüğünü geçici olarak düşürmek', 'Sabit diski birleştirmek', 'Önbelleği büyütmek'], 'Algılama ve kurtarma yaklaşımında bir süreç sonlandırılır ya da kaynağı elinden alınır; böylece döngüsel bekleme kırılır.'),
  ('Bir dosya silindiğinde çoğu dosya sisteminde verinin kendisine ne olur?', 'Bloklar boş işaretlenir, veri üzerine yazılana dek kalır', ['Veri her zaman sıfırlarla anında ve geri dönülmez biçimde silinir', 'Veri RAM\'e taşınır', 'Dosya kendiliğinden yedeklenir'], 'Silme işlemi genellikle yalnız dosya sistemi kayıtlarını günceller; bu yüzden kurtarma araçları silinen dosyaları çoğu zaman geri getirebilir (SSD\'lerde TRIM bunu zorlaştırır).'),
  ('Linux\'ta harici bir diskin içeriğine erişmek için onun dosya sisteminin bir dizine bağlanmasına ne ad verilir?', 'Bağlama (mount)', ['Biçimlendirme (format)', 'Bölümleme (partition)', 'Birleştirme (defragment)'], 'mount komutu bir aygıttaki dosya sistemini /mnt/disk gibi bir bağlama noktasına iliştirir; Windows\'taki sürücü harfi yerine Linux tek bir dizin ağacı kullanır.'),
  ('ReFS, ZFS ve Btrfs gibi yeni nesil dosya sistemlerinin ortak öne çıkan özelliği hangisidir?', 'Bütünlük için sağlama toplamı kullanmaları', ['Yalnızca eski disket sürücülerinde kullanılabilmeleri', 'En çok 4 GB dosyaya izin vermeleri', 'Hiçbir üst veri tutmamaları'], 'Bu dosya sistemleri blokların sağlama toplamını tutarak sessiz veri bozulmasını fark edebilir; ZFS ve Btrfs anlık görüntü özelliği de sunar.'),
  ('Bir bilgisayar açılışta "Önyüklenebilir aygıt bulunamadı" (No bootable device) uyarısı veriyorsa en olası neden hangisidir?', 'Önyükleyicinin bulunduğu diskin görülmemesi', ['Ekran kartının sürücüsünün eski olması', 'Klavyenin Türkçe Q düzeninde olması', 'Monitörün yenileme hızının çok düşük ayarlanmış olması'], 'Ürün yazılımı önyükleme sırasındaki aygıtlarda geçerli bir önyükleyici bulamamıştır; disk bağlantısı, önyükleme sırası ya da bozulmuş önyükleyici denetlenmelidir.'),
  ('Windows\'ta BitLocker özelliği ne işe yarar?', 'Sürücünün tamamını şifreler', ['Diskteki dosyaları birleştirip parçalanmayı giderir', 'Programları uyumluluk modunda çalıştırır', 'Ekran görüntüsü alır'], 'BitLocker tüm birimi şifreler; disk çalınsa bile anahtar olmadan veriler okunamaz. Anahtar çoğunlukla TPM yongasında korunur.'),
  ('Linux\'ta Windows\'takinden farklı olarak program dosyalarının çalıştırılabilir olup olmadığı neyle belirlenir?', 'Dosyanın çalıştırma (x) izniyle', ['Dosya adının .exe ile bitmesiyle', 'Dosyanın simgesinin rengiyle', 'Dosyanın bulunduğu diskin türüyle'], 'Linux\'ta uzantı zorunlu değildir; dosyanın x izni ve içeriği (ikili ya da #! satırlı betik) çalıştırılabilirliği belirler.'),
  ('Bir betik dosyasının ilk satırındaki "#!/bin/bash" ifadesi ne işe yarar?', 'Betiği yorumlayacak programı belirtir', ['Betiğin içeriğini şifreler', 'Betiği yalnızca yöneticiye açık hâle getirir', 'Betiği yorum satırı olarak tamamen devre dışı bırakır'], '"Shebang" denen bu satır, çekirdeğe dosyanın hangi yorumlayıcıyla çalıştırılacağını söyler.'),
  ('Linux\'ta "sudo" kullanılarak çalıştırılan komutlar neden her kullanıcıya açık değildir?', 'Yalnız yetkili listesindekiler çalıştırabilir', ['sudo yalnızca gece saatlerinde çalışan bir komuttur', 'sudo komutu yalnızca grafik arayüzden kullanılabilir', 'Her kullanıcı sudo ile sınırsız yetki alır'], 'sudoers dosyasında ya da sudo/wheel grubunda tanımlı kullanıcılar yetkili komut çalıştırabilir; her kullanım günlüğe kaydedilir.'),
  ('Unix işletim sistemi ilk olarak hangi kurumda geliştirilmiştir?', 'Bell Laboratuvarları', ['Microsoft', 'Xerox PARC', 'Stanford Üniversitesi'], 'Unix 1969\'dan itibaren Bell Labs\'ta Ken Thompson ve Dennis Ritchie tarafından geliştirildi; birçok modern sistemin atasıdır.'),
  ('macOS\'taki "Anahtar Zinciri Erişimi" uygulamasının görevi nedir?', 'Parolaları ve sertifikaları güvenle saklamak', ['Diskleri bölümlendirip yeni dosya sistemiyle biçimlendirmek', 'Ekran görüntüsü almak', 'Uygulamaları zorla kapatmak'], 'Anahtar Zinciri (Keychain), web, Wi-Fi ve uygulama parolalarını ve dijital sertifikaları şifreli bir kasada tutar.'),
  ('Apple\'ın iOS uygulamalarını App Store\'da yayımlamadan önce incelemeden geçirmesinin temel amacı hangisidir?', 'Zararlı ya da kurala aykırı uygulamaları ayıklamak', ['Telefonların her koşulda daha hızlı ve daha güvenli şarj olmasını sağlamak', 'Ekranın daha parlak görünmesini sağlamak', 'İşlemcinin daha az ısınmasını sağlamak'], 'İnceleme süreci, uygulamaları yayından önce güvenlik, gizlilik ve içerik kurallarına göre denetler; sorunlu uygulamalar mağazaya alınmaz.'),
  ('Akıllı telefonlarda "güvenli mod" ile açılış hangi sorunu gidermeye yardımcı olur?', 'Sorunlu bir uygulamayı bulup kaldırmak', ['Ekran camındaki çatlakları onarmak', 'Pilin fiziksel kapasitesini kalıcı olarak artırmak', 'Telefonun işlemcisini değiştirmek'], 'Güvenli modda yalnızca sistem uygulamaları çalışır; sorun bu kipte kayboluyorsa kaynağı sonradan yüklenen bir uygulamadır.'),
  ('Bir otomobilin hava yastığını kaza anında milisaniyeler içinde açan denetim yazılımı için hangi özellik en kritiktir?', 'Belirlenmiş sürede kesin tepki vermesi', ['Renkli bir grafik arayüze sahip olması', 'Çok sayıda kullanıcı hesabını desteklemesi', 'Büyük dosyaları sıkıştırabilmesi'], 'Hava yastığı denetimi katı gerçek zamanlı (hard real-time) bir görevdir; geç verilen doğru yanıt bile başarısızlık sayılır.'),
  ('Mikrodenetleyicilerde programın sıkışıp kalması durumunda sistemi kendiliğinden yeniden başlatan donanım zamanlayıcısına ne ad verilir?', 'Bekçi zamanlayıcısı', ['Gerçek zaman saati (RTC) yongası', 'Program sayacı', 'Kesme denetleyicisi'], 'Program düzenli olarak watchdog\'u sıfırlamazsa süre dolar ve denetleyici kendini yeniden başlatır; uzaktaki cihazlarda takılmaları önler.'),
  ('Süper bilgisayarların neredeyse tamamında hangi işletim sistemi ailesi kullanılır?', 'Linux', ['Windows 3.1', 'MS-DOS', 'Palm OS'], 'Linux açık kaynaklı, özelleştirilebilir ve büyük kümelerde ölçeklenebilir olduğu için süper bilgisayarlarda baskın işletim sistemidir.'),
  ('Bileşenleri en yüksek yükte toplam 380 W çeken bir bilgisayar kuruluyor. Güç kaynağı seçimi için en mantıklı seçenek hangisidir?', 'Kaliteli bir 550 W güç kaynağı', ['Etiketinde 300 W yazan güç kaynağı', 'Etiketinde tam 380 W yazan güç kaynağı', 'Sertifikasız 2000 W güç kaynağı'], 'Güç kaynağının yük artışlarına ve yaşlanmaya karşı pay bırakması, ayrıca verimli aralıkta (yaklaşık %50–80 yük) çalışması önerilir; aşırı büyük ve kalitesiz kaynak ise gereksizdir.'),
  ('Bir bilgisayarda "64 bitlik işlemci" ifadesi genel olarak neyi anlatır?', 'Yazmaçların ve adreslerin 64 bit genişliğinde olmasını', ['İşlemcinin 64 çekirdeğe sahip olmasını', 'İşlemcinin bir saniyede tam olarak 64 milyar işlem yapabilmesini', 'Önbelleğin 64 MB olmasını'], '64 bit mimaride yazmaçlar, tam sayı işlemleri ve adresler 64 bit genişliğindedir; bu, 4 GiB\'tan çok daha fazla belleğin adreslenmesine olanak tanır.'),
  ('Dizüstü bilgisayarlarda HDD yerine SSD kullanılmasının darbe dayanıklılığı açısından yararı nedir?', 'Hareketli parçası olmadığı için darbelerden az etkilenmesi', ['SSD\'nin metal kasasının her türlü darbeyi tamamen sönümlemesi', 'SSD\'nin darbe anında verileri buluta kaydetmesi', 'SSD\'nin dönüş hızını otomatik olarak düşürmesi'], 'HDD\'de çalışma sırasındaki bir darbe kafayı plakaya çarptırabilir; SSD\'de böyle mekanik bir risk yoktur.'),
  ('Ekran kartı belleğinin (VRAM) yetersiz kalması yüksek çözünürlükte oyun oynarken hangi belirtiye yol açabilir?', 'Takılmalar ve düşük doku kalitesi', ['Klavyenin yanıt vermemesi', 'Hoparlörden cızırtı gelmesi', 'Bilgisayarın saatinin geri kalması'], 'Dokular VRAM\'e sığmazsa sistem belleğinden yavaşça taşınır; bu da ani kare düşüşleri ve takılmalar doğurur.'),
  ('Eski CRT ve bazı ekranlarda kullanılan 4:3 en-boy oranıyla karşılaştırıldığında, 16:9 oranının yaygınlaşmasının nedeni hangisidir?', 'Geniş ekran videolara daha uygun olması', ['4:3 ekranların renk gösterememesi', '16:9 ekranların her zaman daha az piksel içermesi', '4:3 oranının yasaklanması'], '16:9 yüksek çözünürlüklü televizyon standardıdır; video içeriğinin çoğu bu oranda üretildiği için siyah şeritler azalır.'),
  ('2560 × 1440 çözünürlüklü bir ekranda kaç piksel bulunur?', '3.686.400', ['2.073.600', '4.000.000', '8.294.400'], '2560 × 1440 = 3.686.400 piksel (yaklaşık 3,7 megapiksel); bu çözünürlüğe QHD ya da 1440p denir.'),
  ('Eski bilgisayarlarda klavye ve farenin bağlandığı, mor ve yeşil renk kodlu yuvarlak bağlantı noktası hangisidir?', 'PS/2', ['VGA', 'HDMI', 'eSATA'], 'PS/2\'de mor klavye, yeşil fare için kullanılır; günümüzde yerini büyük ölçüde USB almıştır.'),
  ('Mimarlık ve mühendislik çizimlerini büyük boyutlu kâğıtlara yüksek doğrulukla basmak için kullanılan çıkış aygıtı hangisidir?', 'Çizici', ['Termal fiş yazıcısı', 'Barkod okuyucu', 'Projeksiyon cihazı'], 'Çiziciler geniş rulo kâğıtlara vektör çizimleri hassasiyetle basar; günümüzde çoğu geniş formatlı mürekkep püskürtmeli yazıcıdır.'),
  ('İşlemci saat hızının yıllar içinde artık eskisi gibi hızla yükselmemesinin başlıca nedeni hangisidir?', 'Yüksek frekansta güç ve ısının aşırı artması', ['İnsan gözünün yüksek frekanstaki değişimleri algılayamaması', 'RAM\'in yüksek frekansta veri saklayamaması', 'Yazılımların yüksek frekansı yasaklaması'], 'Güç kabaca frekans ve gerilimin karesiyle orantılı arttığından ısı sınırı ("güç duvarı") aşılır; üreticiler bu yüzden çekirdek sayısını artırmaya yöneldi.'),
  ('Bir SSD\'nin sıralı okuma hızı 3500 MB/s\'dir. 21 GB\'lık bir oyun dosyası bu hızla yaklaşık kaç saniyede okunur? (1 GB = 1000 MB alınız.)', '6 saniye', ['60 saniye', '0,6 saniye', '16 saniye'], '21.000 MB / 3500 MB/s = 6 saniye.'),
  ('Bir disk görüntüsü (imaj) yedeği almanın dosya dosya yedeklemeye göre üstünlüğü nedir?', 'Sistem dahil tüm diskin olduğu gibi geri yüklenebilmesi', ['Yedeğin her zaman daha az yer kaplaması', 'Yalnızca değişen dosyaların kopyalanması', 'Yedeğin hiçbir zaman güncellenmek ya da yenilenmek zorunda olmaması'], 'Disk görüntüsü bölümleri, önyükleyiciyi ve sistemi içerir; arıza sonrasında bilgisayar kurulum yapmadan eski hâline getirilebilir.'),
  ('Bir yedeğin gerçekten işe yarayıp yaramadığını anlamanın en güvenilir yolu hangisidir?', 'Yedekten deneme geri yüklemesi yapmak', ['Yedek dosyasının boyutuna bakmak', 'Yedek diskin markasını denetlemek', 'Yedek klasörünün adını ve konumunu değiştirmek'], 'Geri yükleme denenmemiş bir yedek bozuk ya da eksik olabilir; düzenli geri yükleme sınamaları yedekleme stratejisinin parçasıdır.'),
  ('500 GB\'lık üç diskten oluşan RAID 0 dizisinin kullanılabilir kapasitesi ne kadardır?', '1,5 TB', ['500 GB', '1 TB', '2 TB'], 'RAID 0 yedeklilik içermediğinden tüm kapasite kullanılır: 3 × 500 GB = 1500 GB = 1,5 TB.'),
  ('Linux\'ta bir dizin için "x" (çalıştırma) izninin anlamı nedir?', 'Dizine girip öğelere erişebilmek', ['Dizindeki dosyaları otomatik çalıştırmak', 'Dizini silebilmek', 'Dizini gizlemek'], 'Dizinlerde r içeriği listelemeyi, w öğe ekleyip silmeyi, x ise dizine girip (cd) içindeki dosyalara yol üzerinden erişmeyi sağlar.'),
];
